import React, { useState } from 'react';
import { Task, TaskStatus, ThemeType, TaskPriority, EisenhowerQuadrant, Unavailability, TaskDifficulty } from '../types';
import { THEMES } from '../constants';
import { CheckCircle2, Clock, Calendar, TrendingUp, Plus, Target, X, Clock3, Sparkles, Loader2, AlertCircle } from 'lucide-react';
import { GoogleGenAI, Type } from '@google/genai';

interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  unavailabilities: Unavailability[];
  onAddTask: (task: any) => void;
  onUpdateTask: (id: string, updates: any) => void;
  onAddUnavailability: (unavail: Omit<Unavailability, 'id'>) => void;
  onDeleteUnavailability: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  tasks, 
  theme, 
  unavailabilities, 
  onAddTask, 
  onUpdateTask,
  onAddUnavailability, 
  onDeleteUnavailability 
}) => {
  const currentTheme = THEMES[theme];
  const [magicInput, setMagicInput] = useState('');
  const [isMagicLoading, setIsMagicLoading] = useState(false);
  const [showUnavailForm, setShowUnavailForm] = useState(false);
  const [newUnavail, setNewUnavail] = useState({ 
    day: 'Lundi', 
    startTime: '08:00', 
    endTime: '12:00', 
    reason: 'Cours' 
  });

  const completedTasks = tasks.filter(t => t.status === TaskStatus.DONE);
  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const urgentTasks = pendingTasks
    .filter(t => t.quadrant === EisenhowerQuadrant.DO_FIRST)
    .slice(0, 3);

  const totalEstimated = tasks.reduce((acc, curr) => acc + curr.estimatedMinutes, 0);
  const progressPercentage = tasks.length > 0 ? Math.round((completedTasks.length / tasks.length) * 100) : 0;

  const days = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

  const handleMagicAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!magicInput.trim()) return;

    setIsMagicLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Analyse cette demande d'étudiant et transforme-la en objet JSON de tâche.
      Texte : "${magicInput}"

      Instructions : 
      - Si c'est urgent ou un examen, utilise 'do_first'. 
      - Estime la durée en minutes (minimum 15).
      - Détermine la difficulté ('easy', 'medium', 'hard').`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              priority: { type: Type.STRING },
              difficulty: { type: Type.STRING },
              quadrant: { type: Type.STRING },
              estimatedMinutes: { type: Type.NUMBER }
            },
            required: ["title", "priority", "difficulty", "quadrant", "estimatedMinutes"]
          }
        }
      });

      const taskData = JSON.parse(response.text || '{}');
      onAddTask({ ...taskData, status: TaskStatus.TODO });
      setMagicInput('');
    } catch (error) {
      console.error("Magic Add Error:", error);
      onAddTask({ 
        title: magicInput, 
        status: TaskStatus.TODO, 
        priority: TaskPriority.MEDIUM, 
        difficulty: TaskDifficulty.MEDIUM, 
        quadrant: EisenhowerQuadrant.DO_FIRST, 
        estimatedMinutes: 30 
      });
      setMagicInput('');
    } finally {
      setIsMagicLoading(false);
    }
  };

  const handleAddUnavail = (e: React.FormEvent) => {
    e.preventDefault();
    onAddUnavailability(newUnavail);
    setShowUnavailForm(false);
  };

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-6 duration-700">
      {/* Statistiques Rapides */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard label="Terminées" value={completedTasks.length.toString()} icon={CheckCircle2} color="text-emerald-500" theme={theme} />
        <StatCard label="En attente" value={pendingTasks.length.toString()} icon={Clock} color="text-amber-500" theme={theme} />
        <StatCard label="Temps estimé" value={`${Math.floor(totalEstimated / 60)}h ${totalEstimated % 60}m`} icon={Calendar} color="text-sky-500" theme={theme} />
        <StatCard label="Focus Score" value={`${progressPercentage}%`} icon={TrendingUp} color="text-fuchsia-500" theme={theme} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-10">
          {/* Saisie Magique IA */}
          <div className={`${currentTheme.card} rounded-[2.5rem] p-8 border-2 border-dashed ${currentTheme.accent} shadow-xl relative group`}>
             <div className="flex items-center gap-3 mb-4">
                <div className="p-2 bg-amber-100 dark:bg-amber-900/30 rounded-lg text-amber-500">
                   <Sparkles size={20} />
                </div>
                <h3 className="font-black text-xl tracking-tight">Magic Add <span className="text-xs opacity-40 font-bold uppercase ml-2 tracking-widest">Powered by Gemini</span></h3>
             </div>
             <form onSubmit={handleMagicAdd} className="relative">
                <textarea 
                   value={magicInput}
                   onChange={(e) => setMagicInput(e.target.value)}
                   placeholder="Ex: 'J'ai un projet d'Histoire à rendre lundi, ça va me prendre 2 heures et c'est super important...'"
                   className="w-full bg-black/5 dark:bg-white/5 border-none rounded-2xl px-6 py-4 text-sm font-medium focus:ring-4 ring-black/5 outline-none transition-all resize-none h-24"
                />
                <button 
                  disabled={isMagicLoading || !magicInput.trim()}
                  className={`absolute bottom-4 right-4 ${currentTheme.button} px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest flex items-center gap-2 shadow-lg disabled:opacity-50 transition-all`}
                >
                   {isMagicLoading ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} strokeWidth={3} />}
                   {isMagicLoading ? 'Analyse...' : 'Ajouter par IA'}
                </button>
             </form>
          </div>

          {/* Tâches Urgentes */}
          <div className="space-y-4">
             <h3 className="font-black text-xl tracking-tight px-2">Action Immédiate</h3>
             <div className="grid gap-3">
                {urgentTasks.length > 0 ? urgentTasks.map(task => (
                  <div key={task.id} className={`${currentTheme.card} p-4 rounded-2xl border ${currentTheme.accent} flex items-center justify-between group hover:scale-[1.01] transition-all shadow-sm`}>
                    <div className="flex items-center gap-4">
                      <div className="w-2 h-10 bg-red-500 rounded-full" />
                      <div>
                        <p className="font-bold text-sm">{task.title}</p>
                        <p className="text-[10px] opacity-40 uppercase font-black">{task.estimatedMinutes} min • Urgent & Important</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })}
                      className="p-2 rounded-xl bg-emerald-50 text-emerald-600 opacity-0 group-hover:opacity-100 transition-all hover:bg-emerald-100"
                    >
                      <CheckCircle2 size={20} />
                    </button>
                  </div>
                )) : (
                  <div className="p-8 text-center bg-black/5 rounded-3xl border border-dashed border-black/10">
                    <p className="text-sm opacity-40 font-bold">Aucune tâche critique pour le moment. Beau travail ! ✨</p>
                  </div>
                )}
             </div>
          </div>
        </div>

        {/* Barre Latérale : Blocages */}
        <div className="space-y-6">
          <div className={`${currentTheme.card} rounded-[2.5rem] p-8 border ${currentTheme.accent} shadow-xl shadow-black/5`}>
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-black text-xl flex items-center gap-3 tracking-tight">
                <Clock3 className={currentTheme.secondary} size={24} /> Blocages
              </h3>
              <button 
                onClick={() => setShowUnavailForm(!showUnavailForm)}
                className="p-2 bg-black/5 rounded-lg hover:bg-black/10 transition-all"
              >
                {showUnavailForm ? <X size={16} /> : <Plus size={16} />}
              </button>
            </div>

            {showUnavailForm && (
              <form onSubmit={handleAddUnavail} className="mb-6 space-y-3 bg-black/5 p-4 rounded-2xl animate-in fade-in zoom-in-95">
                <select 
                  className="w-full bg-white dark:bg-slate-800 rounded-lg p-2 text-xs font-bold"
                  value={newUnavail.day}
                  onChange={e => setNewUnavail({...newUnavail, day: e.target.value})}
                >
                  {days.map(d => <option key={d} value={d}>{d}</option>)}
                </select>
                <div className="flex gap-2">
                  <input type="time" className="flex-1 bg-white dark:bg-slate-800 rounded-lg p-2 text-xs" value={newUnavail.startTime} onChange={e => setNewUnavail({...newUnavail, startTime: e.target.value})} />
                  <input type="time" className="flex-1 bg-white dark:bg-slate-800 rounded-lg p-2 text-xs" value={newUnavail.endTime} onChange={e => setNewUnavail({...newUnavail, endTime: e.target.value})} />
                </div>
                <input type="text" placeholder="Raison (ex: Sport)" className="w-full bg-white dark:bg-slate-800 rounded-lg p-2 text-xs" value={newUnavail.reason} onChange={e => setNewUnavail({...newUnavail, reason: e.target.value})} />
                <button type="submit" className={`w-full ${currentTheme.button} py-2 rounded-lg text-[10px] font-black uppercase`}>Ajouter</button>
              </form>
            )}

            <div className="space-y-3">
               {unavailabilities.length > 0 ? unavailabilities.slice(0, 4).map(u => (
                 <div key={u.id} className="p-4 bg-black/5 rounded-2xl border border-black/5 flex justify-between items-center group">
                    <div>
                       <p className="text-xs font-black">{u.reason}</p>
                       <p className="text-[10px] opacity-40 font-bold uppercase">{u.day} • {u.startTime} - {u.endTime}</p>
                    </div>
                    <button onClick={() => onDeleteUnavailability(u.id)} className="opacity-0 group-hover:opacity-100 text-red-400 hover:text-red-500 transition-all">
                      <X size={14} />
                    </button>
                 </div>
               )) : (
                 <p className="text-[10px] text-center opacity-30 font-bold italic py-4">Aucune contrainte enregistrée.</p>
               )}
            </div>
          </div>

          <div className={`${currentTheme.card} rounded-[2.5rem] p-8 border ${currentTheme.accent} shadow-xl shadow-black/5 border-l-8 border-l-primary`}>
            <div className="flex items-center gap-2 mb-2">
              <AlertCircle size={16} className={currentTheme.secondary} />
              <h3 className="font-black text-sm uppercase tracking-wider">Le Saviez-vous ?</h3>
            </div>
            <p className="text-xs opacity-60 leading-relaxed italic font-bold">
              Une pause de 5 minutes toutes les 25 minutes augmente ta rétention d'informations de 20%. Utilise le mode Focus !
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; icon: any; color: string; theme: ThemeType }> = ({ label, value, icon: Icon, color, theme }) => {
  const currentTheme = THEMES[theme];
  return (
    <div className={`${currentTheme.card} rounded-[2rem] p-6 border ${currentTheme.accent} shadow-xl shadow-black/5 flex items-center gap-5 transition-all hover:-translate-y-2 hover:shadow-2xl`}>
      <div className={`p-4 rounded-2xl bg-black/5 dark:bg-white/5 ${color} shadow-inner`}><Icon size={28} strokeWidth={2.5} /></div>
      <div>
        <p className="text-[11px] font-black opacity-30 uppercase tracking-[0.15em] mb-1">{label}</p>
        <p className="text-2xl font-black tracking-tighter tabular-nums">{value}</p>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Task, ThemeType, TaskStatus, Unavailability } from '../../types';
import { THEMES } from '../../constants';
import { GoogleGenAI, Type } from '@google/genai';
import { Sparkles, CalendarDays, BrainCircuit, Loader2, Info, Lock } from 'lucide-react';

interface SmartPlanningProps {
  tasks: Task[];
  unavailabilities: Unavailability[];
  theme: ThemeType;
}

const SmartPlanning: React.FC<SmartPlanningProps> = ({ tasks, unavailabilities, theme }) => {
  const currentTheme = THEMES[theme];
  const [planning, setPlanning] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [justification, setJustification] = useState('');

  const generatePlanning = async () => {
    setIsLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const activeTasks = tasks.filter(t => t.status !== TaskStatus.DONE);

      const prompt = `Agis comme un expert en productivité EdTech. Voici mes données :

      TACHES :
      ${JSON.stringify(activeTasks.map(t => ({ 
        titre: t.title, 
        priorite: t.priority, 
        difficulte: t.difficulty, 
        quadrant: t.quadrant, 
        duree_estimee: t.estimatedMinutes 
      })))}

      INDISPONIBILITÉS :
      ${JSON.stringify(unavailabilities.map(u => ({
        jour: u.day,
        debut: u.startTime,
        fin: u.endTime,
        raison: u.reason
      })))}

      Génère un planning hebdomadaire optimisé. 
      Règles : 
      1. Respecte strictement les indisponibilités.
      2. Priorise les tâches 'do_first'.
      3. Propose des créneaux précis et réalistes.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              justification: { type: Type.STRING },
              days: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    day: { type: Type.STRING },
                    slots: {
                      type: Type.ARRAY,
                      items: {
                        type: Type.OBJECT,
                        properties: {
                          time: { type: Type.STRING },
                          task: { type: Type.STRING },
                          reason: { type: Type.STRING }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      });

      const result = JSON.parse(response.text || '{}');
      setPlanning(result.days || []);
      setJustification(result.justification || '');
    } catch (error) {
      console.error("AI Error:", error);
      alert("Erreur lors de la génération. Vérifie ta connexion.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-10">
      <div className={`${currentTheme.card} p-8 rounded-[2rem] border ${currentTheme.accent} shadow-xl relative overflow-hidden`}>
        <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none">
          <BrainCircuit size={160} className={currentTheme.secondary} />
        </div>

        <div className="relative z-10">
          <h2 className="text-3xl font-black mb-4 flex items-center gap-3">
            <Sparkles className="text-amber-400" /> Planning Intelligent
          </h2>
          <p className="text-slate-500 max-w-2xl mb-8">
            L'IA analyse tes <span className="font-bold text-slate-800 dark:text-white">{tasks.filter(t => t.status !== TaskStatus.DONE).length} tâches</span> et contourne tes <span className="font-bold text-slate-800 dark:text-white">{unavailabilities.length} contraintes</span> temporelles.
          </p>

          <button 
            onClick={generatePlanning}
            disabled={isLoading || tasks.filter(t => t.status !== TaskStatus.DONE).length === 0}
            className={`${currentTheme.primary} text-white px-8 py-4 rounded-2xl font-bold flex items-center gap-3 shadow-lg hover:opacity-90 transition-all disabled:opacity-50 active:scale-95`}
          >
            {isLoading ? <Loader2 className="animate-spin" /> : <Sparkles />}
            {isLoading ? 'Calcul stratégique...' : 'Optimiser ma semaine'}
          </button>
        </div>
      </div>

      {justification && (
        <div className="bg-amber-50 dark:bg-amber-900/20 p-6 rounded-2xl border border-amber-100 dark:border-amber-900/30 flex items-start gap-3 shadow-sm">
          <Info className="text-amber-500 mt-1 flex-shrink-0" />
          <p className="text-sm text-amber-800 dark:text-amber-200 italic leading-relaxed">{justification}</p>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {planning.length > 0 ? (
          planning.map((dayData, idx) => (
            <div key={idx} className={`${currentTheme.card} p-6 rounded-3xl border ${currentTheme.accent} shadow-sm animate-in slide-in-from-bottom-4 duration-500`} style={{ animationDelay: `${idx * 100}ms` }}>
              <div className="flex justify-between items-center mb-4 border-b pb-2">
                <h3 className="text-xl font-black flex items-center gap-2">
                  <CalendarDays size={20} className={currentTheme.secondary} />
                  {dayData.day}
                </h3>
              </div>
              <div className="space-y-4">
                {dayData.slots.map((slot: any, sIdx: number) => (
                  <div key={sIdx} className="relative pl-4 border-l-2 border-slate-100 dark:border-slate-800 py-1">
                    <div className="absolute left-[-5px] top-2 w-2 h-2 rounded-full bg-slate-300" />
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{slot.time}</span>
                    <p className="font-bold text-sm leading-tight">{slot.task}</p>
                    <p className="text-[10px] text-slate-400 mt-1 italic leading-tight">{slot.reason}</p>
                  </div>
                ))}
              </div>
            </div>
          ))
        ) : !isLoading && (
          <div className="col-span-full py-20 text-center">
            <div className="bg-black/5 rounded-[2rem] p-10 max-w-md mx-auto border-2 border-dashed border-black/10">
               <CalendarDays size={48} className="mx-auto mb-4 opacity-10" />
               <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">
                 {tasks.filter(t => t.status !== TaskStatus.DONE).length === 0 
                   ? "Aucune tâche à planifier."
                   : "Ton planning n'attend qu'un clic."}
               </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SmartPlanning;

export enum TaskStatus {
  TODO = 'todo',
  IN_PROGRESS = 'in_progress',
  DONE = 'done'
}

export enum TaskPriority {
  LOW = 'low',
  MEDIUM = 'medium',
  HIGH = 'high'
}

export enum TaskDifficulty {
  EASY = 'easy',
  MEDIUM = 'medium',
  HARD = 'hard'
}

export enum EisenhowerQuadrant {
  DO_FIRST = 'do_first',      // Urgent & Important
  SCHEDULE = 'schedule',      // Not Urgent & Important
  DELEGATE = 'delegate',      // Urgent & Not Important
  ELIMINATE = 'eliminate'     // Not Urgent & Not Important
}

export enum AppMode {
  STUDY = 'study',
  LEISURE = 'leisure',
  EXTERNAL = 'external'
}

export interface User {
  id: string;
  email: string;
  name: string;
  avatar?: string;
}

export interface Unavailability {
  id: string;
  day: string; // 'Lundi', 'Mardi', etc.
  startTime: string;
  endTime: string;
  reason: string;
}

export interface Task {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
  priority: TaskPriority;
  difficulty: TaskDifficulty;
  quadrant: EisenhowerQuadrant;
  dueDate?: string;
  estimatedMinutes: number;
  actualMinutes: number;
  createdAt: number;
  completedAt?: number;
}

export type ThemeType = 'lime' | 'emerald' | 'blue' | 'purple' | 'dark';

export interface UserData {
  tasks: Task[];
  unavailabilities: Unavailability[];
  theme: ThemeType;
}

export interface AppState {
  user: User | null;
  data: UserData;
}

