import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus,
  LogOut,
  Sparkles,
  Settings
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, AppMode } from './types';
import { THEMES } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ModeSelector from './components/ModeSelector';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [appMode, setAppMode] = useState<AppMode | null>(null);
  const [data, setData] = useState<UserData>({ tasks: [], unavailabilities: [], theme: 'emerald' });
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);
  const [isLoading, setIsLoading] = useState(true);

  // Persistence logic
  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      setUser(u);
      loadUserData(u.id);
    } else {
      setIsLoading(false);
    }
  }, []);

  const loadUserData = async (userId: string) => {
    try {
      const userData = await mockAuthService.getUserData(userId);
      setData(userData);
    } catch (err) {
      console.error("Failed to load user data", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('evo_current_user', JSON.stringify(u));
    loadUserData(u.id);
  };

  const handleLogout = () => {
    setUser(null);
    setAppMode(null);
    localStorage.removeItem('evo_current_user');
  };

  const updateData = (newData: Partial<UserData>) => {
    const updated = { ...data, ...newData };
    setData(updated);
    if (user) mockAuthService.saveUserData(user.id, updated);
  };

  const handleAddTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      actualMinutes: 0,
      createdAt: Date.now(),
    };
    updateData({ tasks: [newTask, ...data.tasks] });
    setIsTaskModalOpen(false);
  };

  const handleUpdateTask = (id: string, updates: Partial<Task>) => {
    const newTasks = data.tasks.map(t => 
      t.id === id ? { ...t, ...updates, completedAt: updates.status === TaskStatus.DONE ? Date.now() : t.completedAt } : t
    );
    updateData({ tasks: newTasks });
  };

  const handleDeleteTask = (id: string) => {
    updateData({ tasks: data.tasks.filter(t => t.id !== id) });
  };

  const handleAddUnavailability = (unavail: Omit<Unavailability, 'id'>) => {
    const newU: Unavailability = { ...unavail, id: Math.random().toString(36).substr(2, 9) };
    updateData({ unavailabilities: [...data.unavailabilities, newU] });
  };

  const handleDeleteUnavailability = (id: string) => {
    updateData({ unavailabilities: data.unavailabilities.filter(u => u.id !== id) });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">Initialisation d'Evo...</p>
        </div>
      </div>
    );
  }

  if (!user) return <AuthScreen onLogin={handleLogin} />;

  // Transition after login: Mode Selection
  if (!appMode) {
    return (
      <ModeSelector 
        userName={user.name} 
        theme={data.theme} 
        onSelect={(mode) => setAppMode(mode)} 
      />
    );
  }

  const currentTheme = THEMES[data.theme];

  const renderView = () => {
    switch(currentView) {
      case 'dashboard': return (
        <Dashboard 
          tasks={data.tasks} 
          theme={data.theme} 
          unavailabilities={data.unavailabilities}
          onAddTask={handleAddTask}
          onUpdateTask={handleUpdateTask}
          onAddUnavailability={handleAddUnavailability}
          onDeleteUnavailability={handleDeleteUnavailability}
        />
      );
      case 'tasks': return (
        <TodoList 
          tasks={data.tasks} 
          theme={data.theme} 
          onUpdateTask={handleUpdateTask}
          onDeleteTask={handleDeleteTask}
          onEditTask={(task) => { setEditingTask(task); setIsTaskModalOpen(true); }}
          onAddTask={() => { setEditingTask(undefined); setIsTaskModalOpen(true); }}
        />
      );
      case 'matrix': return (
        <EisenhowerMatrix 
          tasks={data.tasks} 
          theme={data.theme} 
          onUpdateTask={handleUpdateTask} 
        />
      );
      case 'focus': return (
        <Pomodoro 
          theme={data.theme} 
          tasks={data.tasks} 
          onUpdateTask={handleUpdateTask} 
        />
      );
      case 'stats': return (
        <ProgressTracking 
          tasks={data.tasks} 
          theme={data.theme} 
        />
      );
      case 'planning': return (
        <SmartPlanning 
          tasks={data.tasks} 
          unavailabilities={data.unavailabilities} 
          theme={data.theme} 
        />
      );
      default: return null;
    }
  };

  return (
    <div className={`min-h-screen ${currentTheme.bg} ${currentTheme.text} transition-all duration-500 pb-20 lg:pb-0 lg:pl-24`}>
      {/* Sidebar (Desktop) */}
      <aside className={`fixed left-0 top-0 bottom-0 w-24 hidden lg:flex flex-col items-center py-10 bg-white/50 dark:bg-black/20 backdrop-blur-3xl border-r ${currentTheme.accent} z-50`}>
        <div className={`w-12 h-12 ${currentTheme.primary} rounded-2xl flex items-center justify-center text-white mb-12 shadow-lg shadow-primary/20`}>
          <Sparkles size={24} />
        </div>

        <nav className="flex flex-col gap-6 flex-1">
          <NavIcon icon={LayoutDashboard} active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} theme={data.theme} label="Home" />
          <NavIcon icon={CheckSquare} active={currentView === 'tasks'} onClick={() => setCurrentView('tasks')} theme={data.theme} label="Tasks" />
          <NavIcon icon={Grid2X2} active={currentView === 'matrix'} onClick={() => setCurrentView('matrix')} theme={data.theme} label="Matrix" />
          <NavIcon icon={CalendarDays} active={currentView === 'planning'} onClick={() => setCurrentView('planning')} theme={data.theme} label="Plan" />
          <NavIcon icon={Timer} active={currentView === 'focus'} onClick={() => setCurrentView('focus')} theme={data.theme} label="Focus" />
          <NavIcon icon={BarChart3} active={currentView === 'stats'} onClick={() => setCurrentView('stats')} theme={data.theme} label="Stats" />
        </nav>

        <div className="flex flex-col gap-4 mt-auto">
          <button onClick={() => setAppMode(null)} className="p-3 text-slate-400 hover:text-slate-600 transition-colors" title="Changer de mode">
            <Settings size={22} />
          </button>
          <button onClick={handleLogout} className="p-3 text-red-400 hover:text-red-500 transition-colors">
            <LogOut size={22} />
          </button>
        </div>
      </aside>

      {/* Mobile Bottom Nav */}
      <nav className={`fixed bottom-0 left-0 right-0 h-16 bg-white/80 dark:bg-black/60 backdrop-blur-2xl border-t ${currentTheme.accent} flex items-center justify-around lg:hidden z-50 px-4`}>
        <NavIcon icon={LayoutDashboard} active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} theme={data.theme} mobile />
        <NavIcon icon={CheckSquare} active={currentView === 'tasks'} onClick={() => setCurrentView('tasks')} theme={data.theme} mobile />
        <div className="relative -top-6">
          <button 
            onClick={() => { setEditingTask(undefined); setIsTaskModalOpen(true); }}
            className={`w-14 h-14 ${currentTheme.primary} rounded-full text-white shadow-xl flex items-center justify-center border-4 border-white dark:border-slate-900`}
          >
            <Plus size={28} />
          </button>
        </div>
        <NavIcon icon={Timer} active={currentView === 'focus'} onClick={() => setCurrentView('focus')} theme={data.theme} mobile />
        <NavIcon icon={Settings} active={false} onClick={() => setAppMode(null)} theme={data.theme} mobile />
      </nav>

      {/* Top Header */}
      <header className="p-6 lg:p-10 flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-black tracking-tight flex items-center gap-3">
             {currentView.charAt(0).toUpperCase() + currentView.slice(1)}
             <span className={`text-[10px] px-2 py-0.5 rounded-full ${currentTheme.primary} text-white uppercase tracking-widest font-black`}>
               {appMode === AppMode.STUDY ? 'Études' : appMode === AppMode.LEISURE ? 'Loisir' : 'Externe'}
             </span>
          </h2>
          <p className="text-sm font-medium text-slate-400">Prêt pour une session productive ?</p>
        </div>

        <div className="flex items-center gap-4">
           <div className="hidden sm:flex flex-col items-end mr-2">
             <p className="text-sm font-black">{user.name}</p>
             <p className="text-[10px] opacity-40 uppercase tracking-widest font-bold">Lvl 1 • Novice</p>
           </div>
           <button 
             onClick={() => { setEditingTask(undefined); setIsTaskModalOpen(true); }}
             className={`hidden sm:flex items-center gap-2 ${currentTheme.button} px-6 py-3 rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl transition-all`}
           >
             <Plus size={16} strokeWidth={3} /> Nouvelle Tâche
           </button>
           <div className="w-12 h-12 rounded-2xl bg-slate-200 overflow-hidden border-2 border-white shadow-md">
             <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${user.email}`} alt="Avatar" />
           </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 lg:px-10">
        {renderView()}
      </main>

      {/* Task Modal */}
      {isTaskModalOpen && (
        <TaskModal 
          theme={data.theme}
          task={editingTask}
          onClose={() => setIsTaskModalOpen(false)}
          onSubmit={editingTask ? (updates) => { handleUpdateTask(editingTask.id, updates); setIsTaskModalOpen(false); } : handleAddTask}
        />
      )}
    </div>
  );
};

const NavIcon = ({ icon: Icon, active, onClick, theme, label, mobile }: { 
  icon: any; 
  active: boolean; 
  onClick: () => void; 
  theme: ThemeType; 
  label?: string;
  mobile?: boolean;
}) => {
  const currentTheme = THEMES[theme];
  return (
    <button 
      onClick={onClick}
      className={`group relative p-3 rounded-2xl transition-all duration-300 flex flex-col items-center gap-1 ${
        active 
        ? `${currentTheme.primary} text-white shadow-lg shadow-primary/30` 
        : 'text-slate-400 hover:bg-slate-100 dark:hover:bg-white/5 hover:text-slate-600'
      }`}
    >
      <Icon size={mobile ? 24 : 22} strokeWidth={active ? 2.5 : 2} />
      {label && !mobile && (
        <span className="absolute left-full ml-4 px-3 py-1 bg-slate-800 text-white text-[10px] rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-50 font-bold uppercase tracking-widest">
          {label}
        </span>
      )}
    </button>
  );
};

