import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus,
  LogOut,
  Sparkles,
  Settings,
  Trophy
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, AppMode } from './types';
import { THEMES } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ModeSelector from './components/ModeSelector';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning';

const XP_PER_TASK = 25;

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [appMode, setAppMode] = useState<AppMode | null>(null);
  const [data, setData] = useState<UserData>({ tasks: [], unavailabilities: [], theme: 'dark_blue' });
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      setUser(u);
      loadUserData(u.id);
    } else {
      setIsLoading(false);
    }
  }, []);

  const loadUserData = async (userId: string) => {
    try {
      const userData = await mockAuthService.getUserData(userId);
      setData(userData);
    } catch (err) {
      console.error("Failed to load user data", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('evo_current_user', JSON.stringify(u));
    loadUserData(u.id);
  };

  const handleLogout = () => {
    setUser(null);
    setAppMode(null);
    localStorage.removeItem('evo_current_user');
  };

  const updateData = (newData: Partial<UserData>) => {
    const updated = { ...data, ...newData };
    setData(updated);
    if (user) mockAuthService.saveUserData(user.id, updated);
  };

  const calculateLevel = (xp: number) => Math.floor(Math.sqrt(xp / 50)) + 1;

  const handleAddTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      actualMinutes: 0,
      createdAt: Date.now(),
    };
    updateData({ tasks: [newTask, ...data.tasks] });
    setIsTaskModalOpen(false);
  };

  const handleUpdateTask = (id: string, updates: Partial<Task>) => {
    const newTasks = data.tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone && user) {
          const newXp = (user.xp || 0) + XP_PER_TASK;
          const newLevel = calculateLevel(newXp);
          const updatedUser = { ...user, xp: newXp, level: newLevel };
          setUser(updatedUser);
          localStorage.setItem('evo_current_user', JSON.stringify(updatedUser));
        }
        return { ...t, ...updates, completedAt: updates.status === TaskStatus.DONE ? Date.now() : t.completedAt };
      }
      return t;
    });
    updateData({ tasks: newTasks });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-xs font-black text-indigo-400 uppercase tracking-widest animate-pulse">Evo Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) return <AuthScreen onLogin={handleLogin} />;

  if (!appMode) {
    return <ModeSelector userName={user.name} theme={data.theme} onSelect={(mode) => setAppMode(mode)} />;
  }

  const currentTheme = THEMES[data.theme];

  return (
    <div className={`min-h-screen ${currentTheme.bg} ${currentTheme.text} transition-all duration-700 pb-20 lg:pb-0 lg:pl-24`}>
      {/* Sidebar (Desktop) */}
      <aside className={`fixed left-0 top-0 bottom-0 w-24 hidden lg:flex flex-col items-center py-10 bg-black/40 backdrop-blur-3xl border-r ${currentTheme.accent} z-50 shadow-2xl shadow-black/50`}>
        <div className={`w-12 h-12 ${currentTheme.primary} rounded-2xl flex items-center justify-center text-white mb-12 shadow-xl shadow-primary/20 cursor-pointer hover:rotate-12 transition-transform`}>
          <Sparkles size={24} />
        </div>

        <nav className="flex flex-col gap-8 flex-1">
          <NavIcon icon={LayoutDashboard} active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} theme={data.theme} label="Home" />
          <NavIcon icon={CheckSquare} active={currentView === 'tasks'} onClick={() => setCurrentView('tasks')} theme={data.theme} label="Tasks" />
          <NavIcon icon={Grid2X2} active={currentView === 'matrix'} onClick={() => setCurrentView('matrix')} theme={data.theme} label="Matrix" />
          <NavIcon icon={CalendarDays} active={currentView === 'planning'} onClick={() => setCurrentView('planning')} theme={data.theme} label="Plan" />
          <NavIcon icon={Timer} active={currentView === 'focus'} onClick={() => setCurrentView('focus')} theme={data.theme} label="Focus" />
