        <div className="lg:col-span-2 space-y-10">
          {/* AI Magic Input */}
          <div className={`${currentTheme.card} ${modeStyle.cardRadius} ${modeStyle.glow} p-8 border ${currentTheme.accent} relative group overflow-hidden`}>
