             <div className="flex items-center gap-4 mb-6">
                <div className={`p-3 rounded-2xl bg-indigo-500/10 text-indigo-400`}>
                   <Sparkles size={24} />
                </div>
                <h3 className={`${modeStyle.titleFont} text-2xl tracking-tighter`}>
                  Magic Add
                  <span className="ml-3 text-[10px] opacity-30 uppercase font-black tracking-widest">IA Powered</span>
                </h3>
             </div>

             <form onSubmit={handleMagicAdd} className="relative">
                <textarea 
                   value={magicInput}
                   onChange={(e) => setMagicInput(e.target.value)}
                   placeholder={appMode === AppMode.STUDY ? "J'ai un examen d'Anglais à préparer pour demain..." : appMode === AppMode.LEISURE ? "Organiser une soirée pizza vendredi !" : "Vérifier les factures d'électricité..."}
                   className="w-full bg-slate-950/50 border border-white/5 rounded-2xl px-6 py-5 text-sm font-medium focus:ring-4 ring-indigo-500/20 outline-none transition-all resize-none h-32"
