                >
                   {isMagicLoading ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} strokeWidth={3} />}
                   {isMagicLoading ? 'Analysing...' : 'Submit'}
                </button>
             </form>
          </div>

          {/* Urgent Tasks */}
          <div className="space-y-6">
            <h3 className={`${modeStyle.titleFont} text-xl flex items-center gap-3`}>
