           <div className={`${currentTheme.card} ${modeStyle.cardRadius} p-8 border ${currentTheme.accent} border-l-4 border-l-indigo-500`}>
              <h4 className={`${modeStyle.titleFont} text-xs uppercase tracking-widest text-slate-500 mb-4`}>Conseil du Jour</h4>
              <p className="text-sm font-medium italic opacity-60 leading-relaxed text-slate-300">
                "La productivité n'est pas de faire plus, mais de faire mieux ce qui compte vraiment."
              </p>
           </div>
        </div>
      </div>
    </div>
  );
};

