          <NavIcon icon={CalendarDays} active={currentView === 'planning'} onClick={() => setCurrentView('planning')} theme={data.theme} appMode={appMode} label="Plan" />
          <NavIcon icon={Timer} active={currentView === 'focus'} onClick={() => setCurrentView('focus')} theme={data.theme} appMode={appMode} label="Focus" />
