               </div>
               <div className={`absolute -bottom-2 -right-2 ${currentTheme.primary} text-white w-10 h-10 ${modeStyle.radius} flex items-center justify-center font-black text-xs border-4 border-slate-950 shadow-xl`}>
                 {user.level}
               </div>
            </div>
            <div className="mb-4">
              <div className="flex items-center gap-3">
                <h2 className="text-4xl font-black tracking-tighter drop-shadow-lg">{user.name}</h2>
                <div className="flex gap-1">
                  {user.traits?.slice(0, 3).map(trait => (
                    <span key={trait} className={`text-[8px] px-2 py-0.5 ${modeStyle.radius} bg-white/10 text-white/80 uppercase font-black tracking-widest border border-white/5`}>{trait}</span>
