import React, { useState } from 'react';
import { Task, TaskStatus, ThemeType, AppMode, Unavailability, EisenhowerQuadrant } from '../types';
import { THEMES, MODE_CONFIG } from '../constants';
import { CheckCircle2, Clock, Sparkles, Loader2, Plus, Zap, AlertCircle } from 'lucide-react';
import { GoogleGenAI, Type } from '@google/genai';

interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  appMode: AppMode;
  unavailabilities: Unavailability[];
  onAddTask: (task: any) => void;
  onUpdateTask: (id: string, updates: any) => void;
  onAddUnavailability: (unavail: Omit<Unavailability, 'id'>) => void;
  onDeleteUnavailability: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  tasks, 
  theme, 
  appMode,
  unavailabilities, 
  onAddTask, 
  onUpdateTask,
}) => {
  const currentTheme = THEMES[theme];
  const modeStyle = MODE_CONFIG[appMode];
  const [magicInput, setMagicInput] = useState('');
  const [isMagicLoading, setIsMagicLoading] = useState(false);

  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const completedToday = tasks.filter(t => t.status === TaskStatus.DONE && t.completedAt && new Date(t.completedAt).toDateString() === new Date().toDateString()).length;

  const handleMagicAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!magicInput.trim()) return;
    setIsMagicLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Convertis cette demande pour le mode "${appMode}" en tâche JSON. Texte: "${magicInput}"`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              priority: { type: Type.STRING },
              difficulty: { type: Type.STRING },
              quadrant: { type: Type.STRING },
              estimatedMinutes: { type: Type.NUMBER }
            },
            required: ["title", "priority", "difficulty", "quadrant", "estimatedMinutes"]
          }
        }
      });
      const taskData = JSON.parse(response.text || '{}');
      onAddTask({ ...taskData, status: TaskStatus.TODO });
      setMagicInput('');
    } catch (e) {
      console.error(e);
    } finally {
      setIsMagicLoading(false);
    }
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      {/* Dynamic Stats Grid */}
      <div className={`grid ${modeStyle.statsStyle} gap-6`}>
        <StatCard label="Inbox" value={pendingTasks.length.toString()} icon={Zap} color={modeStyle.iconColor} theme={theme} appMode={appMode} />
        <StatCard label="Streak" value={completedToday.toString()} icon={CheckCircle2} color="text-emerald-400" theme={theme} appMode={appMode} />
        <StatCard label="Score XP" value={(tasks.filter(t => t.status === TaskStatus.DONE).length * 35).toString()} icon={Sparkles} color="text-amber-400" theme={theme} appMode={appMode} />
        <StatCard label="Dispo" value={`${unavailabilities.length}`} icon={Clock} color="text-indigo-400" theme={theme} appMode={appMode} />
      </div>

      <div className={`grid grid-cols-1 ${appMode === AppMode.EXTERNAL ? 'lg:grid-cols-1' : 'lg:grid-cols-3'} gap-10`}>
        <div className={`${appMode === AppMode.EXTERNAL ? '' : 'lg:col-span-2'} space-y-10`}>

          {/* MAGIC ADD (Only for non-study modes) */}
          {modeStyle.magicAdd && (
            <div className={`${currentTheme.card} ${modeStyle.radius} ${modeStyle.glow} p-8 border ${currentTheme.accent} relative group overflow-hidden transition-all duration-500`}>
               {appMode === AppMode.LEISURE && (
                 <div className="absolute -top-10 -right-10 w-48 h-48 bg-pink-500/10 rounded-full blur-[80px] group-hover:bg-pink-500/20 transition-all duration-700" />
               )}

               <div className="flex items-center gap-4 mb-6">
                  <div className={`p-3 ${modeStyle.radius} bg-indigo-500/10 ${modeStyle.iconColor} shadow-inner`}>
                     <Sparkles size={24} />
                  </div>
                  <h3 className={`text-2xl font-black tracking-tighter`}>
                    Capture {appMode === AppMode.LEISURE ? 'Loisir' : 'Pro'}
                    <span className="ml-4 text-[9px] opacity-30 uppercase font-black tracking-[0.3em]">IA Active</span>
                  </h3>
               </div>

               <form onSubmit={handleMagicAdd} className="relative">
                  <textarea 
                     value={magicInput}
                     onChange={(e) => setMagicInput(e.target.value)}
                     placeholder={appMode === AppMode.LEISURE ? "Organiser un petit barbecue dimanche..." : "Rédaction du compte-rendu hebdomadaire."}
                     className={`w-full bg-black/30 border border-white/5 ${modeStyle.innerRadius} px-6 py-5 text-sm font-medium focus:ring-4 ring-indigo-500/10 outline-none transition-all resize-none h-32 ${appMode === AppMode.EXTERNAL ? 'font-mono uppercase text-[12px]' : ''}`}
                  />
                  <button 
                    disabled={isMagicLoading || !magicInput.trim()}
                    className={`absolute bottom-4 right-4 ${currentTheme.button} ${modeStyle.radius} px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-2xl disabled:opacity-50 hover:scale-105 transition-all`}
                  >
                     {isMagicLoading ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} strokeWidth={3} />}
                     Submit
                  </button>
               </form>
            </div>
          )}

          {/* Task Focus Section */}
          <div className="space-y-6">
            <h3 className={`text-xl font-black flex items-center gap-3 ${appMode === AppMode.EXTERNAL ? 'uppercase tracking-widest border-b border-white/5 pb-2' : ''}`}>
               <AlertCircle size={20} className="text-red-500" /> 
               {appMode === AppMode.STUDY ? 'Priorités de Révision' : appMode === AppMode.LEISURE ? 'À faire absolument !' : 'Action Items Critiques'}
            </h3>
            <div className={`grid gap-4 ${appMode === AppMode.EXTERNAL ? 'grid-cols-2' : 'grid-cols-1'}`}>
               {pendingTasks.slice(0, 4).map(task => (
                 <div key={task.id} className={`${currentTheme.card} ${modeStyle.radius} p-5 border ${currentTheme.accent} flex items-center justify-between group hover:border-indigo-500/30 transition-all ${modeStyle.glow}`}>
                    <div className="flex items-center gap-5">
                       <div className={`w-12 h-12 ${modeStyle.radius} bg-slate-950/50 flex items-center justify-center border border-white/5 group-hover:bg-indigo-500/10 transition-colors`}>
                          <Zap size={20} className={task.quadrant === EisenhowerQuadrant.DO_FIRST ? 'text-red-500' : 'text-slate-500'} />
                       </div>
                       <div>
                          <p className={`font-bold text-sm tracking-tight ${appMode === AppMode.EXTERNAL ? 'uppercase' : ''}`}>{task.title}</p>
                          <div className="flex items-center gap-2 mt-1">
                             <span className="text-[9px] font-black uppercase tracking-widest opacity-40">{task.estimatedMinutes}m</span>
                             <span className={`text-[8px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded-md bg-white/5`}>{task.difficulty}</span>
                          </div>
                       </div>
                    </div>
                    <button 
                      onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })}
                      className={`p-3 bg-emerald-500/10 text-emerald-500 ${modeStyle.radius} hover:bg-emerald-500 hover:text-white transition-all shadow-lg opacity-0 group-hover:opacity-100`}
                    >
                      <CheckCircle2 size={18} />
                    </button>
                 </div>
               ))}
               {pendingTasks.length === 0 && (
                 <div className={`p-10 text-center ${currentTheme.card} ${modeStyle.radius} border-2 border-dashed border-white/5`}>
                   <p className="text-xs font-black uppercase tracking-widest opacity-20">Rien de urgent. Profite !</p>
                 </div>
               )}
            </div>
          </div>
        </div>

        {/* SIDEBAR WIDGETS (Only for Study and Leisure) */}
        {appMode !== AppMode.EXTERNAL && (
          <div className="space-y-8">
             <div className={`${currentTheme.card} ${modeStyle.radius} ${modeStyle.glow} p-8 border ${currentTheme.accent} relative overflow-hidden`}>
                <div className="absolute -left-4 -bottom-4 opacity-5 pointer-events-none">
                   <Clock size={120} />
                </div>
                <h4 className={`text-xs uppercase tracking-[0.2em] text-slate-500 mb-8 flex items-center gap-2 font-black`}>
                   <Clock size={16} /> Focus Session
                </h4>
                <div className="text-center py-4">
                   <div className={`text-6xl font-black tabular-nums tracking-tighter ${appMode === AppMode.LEISURE ? 'text-pink-400 drop-shadow-[0_0_15px_rgba(236,72,153,0.4)]' : 'text-emerald-400'}`}>
                     25:00
                   </div>
                   <p className="text-[10px] font-black text-slate-500 uppercase mt-2 tracking-widest">Pomodoro Cycle</p>
                   <button className={`mt-10 w-full ${currentTheme.button} ${modeStyle.radius} py-4 font-black text-[10px] uppercase tracking-widest shadow-2xl transition-all hover:scale-[1.02] active:scale-95`}>
                     Démarrer le focus
                   </button>
                </div>
             </div>

             <div className={`${currentTheme.card} ${modeStyle.radius} p-8 border ${currentTheme.accent} border-l-4 border-l-indigo-500 relative`}>
                <Sparkles className="absolute top-4 right-4 text-indigo-500/20" size={24} />
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-4">Système Evo</h4>
                <p className="text-sm font-medium italic opacity-60 leading-relaxed text-slate-300">
                  "Chaque session d'étude réussie t'apporte {appMode === AppMode.LEISURE ? 'du temps pour jouer' : 'des points de niveau'}."
                </p>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

const StatCard = ({ label, value, icon: Icon, color, theme, appMode }: any) => {
  const currentTheme = THEMES[theme as ThemeType];
  const modeStyle = MODE_CONFIG[appMode as AppMode];
  return (
    <div className={`${currentTheme.card} ${modeStyle.radius} p-6 border ${currentTheme.accent} hover:-translate-y-1 transition-all duration-300 relative group overflow-hidden`}>
      {appMode === AppMode.LEISURE && (
        <div className={`absolute inset-0 bg-gradient-to-br from-indigo-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity`} />
      )}
      <div className="flex items-center gap-5 relative z-10">
        <div className={`p-4 ${modeStyle.radius} bg-slate-950/80 ${color} shadow-2xl group-hover:scale-110 transition-transform`}>
          <Icon size={24} />
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-0.5">{label}</p>
          <p className={`text-3xl font-black tracking-tighter ${appMode === AppMode.EXTERNAL ? 'font-mono' : ''}`}>{value}</p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

