            <div className="relative group">
               <div className={`w-36 h-36 ${modeStyle.radius} bg-slate-900 border-[10px] border-slate-950 overflow-hidden shadow-2xl relative`}>
                 <img src={user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.email}`} alt="Avatar" className="w-full h-full object-cover" />
                 {user.level >= 10 && (
