            </div>
            <div className="mb-4">
              <div className="flex items-center gap-3">
                <h2 className="text-4xl font-black tracking-tighter drop-shadow-lg">{user.name}</h2>
                <div className="flex gap-1">
                  {user.traits?.slice(0, 3).map(trait => (
