    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      if (isLogin) {
        const user = await mockAuthService.login(formData.email, formData.password);
        onLogin(user);
      } else {
        const user = await mockAuthService.signup(formData.email, formData.name, formData.password);
        onLogin(user);
      }
