          )}

          <div className="relative group">
            <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-indigo-400 transition-colors" size={20} />
            <input
              required
              type="email"
              placeholder="ADRESSE EMAIL"
              value={formData.email}
              onChange={(e) => setFormData({...formData, email: e.target.value})}
              className="w-full bg-slate-950 border border-white/5 rounded-2xl pl-12 pr-4 py-5 text-xs font-bold uppercase tracking-widest focus:ring-4 ring-indigo-500/10 outline-none transition-all text-white placeholder:text-slate-700"
            />
