import { User, UserData, TaskStatus, TaskPriority, EisenhowerQuadrant, ThemeType } from '../types';

const USERS_DB_KEY = 'evo_sql_users';
const DATA_DB_PREFIX = 'evo_sql_data_';

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

export const mockAuthService = {
  async signup(email: string, name: string, password: string): Promise<User> {
    await delay(800);
    const users: any[] = JSON.parse(localStorage.getItem(USERS_DB_KEY) || '[]');

    if (users.find(u => u.email === email)) {
      throw new Error("Cet email est déjà utilisé.");
    }

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      email,
      name,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${email}`,
      level: 1,
      xp: 0,
      traits: ['Nouveau venu'],
      bannerColor: 'from-indigo-600 via-purple-600 to-pink-600',
      unlockedGifs: false,
      unlockedBanners: false
    };

    users.push({ ...newUser, password }); 
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

    const defaultData: UserData = {
      tasks: [],
      unavailabilities: [],
      theme: 'dark_blue'
    };
    localStorage.setItem(`${DATA_DB_PREFIX}${newUser.id}`, JSON.stringify(defaultData));

    return newUser;
  },

  async login(email: string, password: string): Promise<User> {
    await delay(600);
    const users: any[] = JSON.parse(localStorage.getItem(USERS_DB_KEY) || '[]');
    const user = users.find(u => u.email === email && u.password === password);

    if (!user) {
      throw new Error("Email ou mot de passe incorrect.");
    }

    const { password: _, ...userWithoutPassword } = user;
    return userWithoutPassword as User;
  },

  async getUserData(userId: string): Promise<UserData> {
    await delay(300);
    const data = localStorage.getItem(`${DATA_DB_PREFIX}${userId}`);
    return data ? JSON.parse(data) : { tasks: [], unavailabilities: [], theme: 'dark_blue' };
  },

  async saveUserData(userId: string, data: UserData): Promise<void> {
    localStorage.setItem(`${DATA_DB_PREFIX}${userId}`, JSON.stringify(data));
  }
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus,
  LogOut,
  Sparkles,
  Settings,
  Trophy,
  Zap
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, AppMode, TaskDifficulty } from './types';
import { THEMES, MODE_CONFIG } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ModeSelector from './components/ModeSelector';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning' | 'settings';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [appMode, setAppMode] = useState<AppMode | null>(null);
  const [data, setData] = useState<UserData>({ tasks: [], unavailabilities: [], theme: 'dark_blue' });
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      const u = JSON.parse(savedUser);
      setUser(u);
      loadUserData(u.id);
    } else {
      setIsLoading(false);
    }
  }, []);

  const loadUserData = async (userId: string) => {
    try {
      const userData = await mockAuthService.getUserData(userId);
      setData(userData);
    } catch (err) {
      console.error("Failed to load user data", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('evo_current_user', JSON.stringify(u));
    loadUserData(u.id);
  };

  const handleLogout = () => {
    setUser(null);
    setAppMode(null);
    localStorage.removeItem('evo_current_user');
  };

  const calculateLevel = (xp: number) => Math.floor(xp / 1000) + 1;

  const handleUpdateUser = (updates: Partial<User>) => {
    if (!user) return;
    const updatedUser = { ...user, ...updates };
    setUser(updatedUser);
    localStorage.setItem('evo_current_user', JSON.stringify(updatedUser));
  };

  const handleAddTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      actualMinutes: 0,
      createdAt: Date.now(),
    };
    const newTasks = [newTask, ...data.tasks];
    setData({ ...data, tasks: newTasks });
    if (user) mockAuthService.saveUserData(user.id, { ...data, tasks: newTasks });
    setIsTaskModalOpen(false);
  };

  const handleUpdateTask = (id: string, updates: Partial<Task>) => {
    const newTasks = data.tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone && user) {
          // New XP System based on difficulty
          let gainedXP = 100; // Easy
          if (t.difficulty === TaskDifficulty.MEDIUM) gainedXP = 150;
          if (t.difficulty === TaskDifficulty.HARD) gainedXP = 200;

          const newXp = (user.xp || 0) + gainedXP;
          const newLevel = calculateLevel(newXp);

          const updatedUser = { 
            ...user, 
            xp: newXp, 
            level: newLevel,
            unlockedBanners: newLevel >= 3,
            unlockedGifs: newLevel >= 10,
            traits: newLevel > 5 && !user.traits.includes('Vétéran') ? [...user.traits, 'Vétéran'] : user.traits 
          };
          setUser(updatedUser);
          localStorage.setItem('evo_current_user', JSON.stringify(updatedUser));
        }
        return { ...t, ...updates, completedAt: updates.status === TaskStatus.DONE ? Date.now() : t.completedAt };
      }
      return t;
    });
    setData({ ...data, tasks: newTasks });
    if (user) mockAuthService.saveUserData(user.id, { ...data, tasks: newTasks });
  };

  if (isLoading) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950">
      <div className="flex flex-col items-center gap-4">
        <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
        <p className="text-xs font-black text-indigo-400 uppercase tracking-widest animate-pulse">Evo Loading...</p>
      </div>
    </div>
  );

  if (!user) return <AuthScreen onLogin={handleLogin} />;
  if (!appMode) return <ModeSelector userName={user.name} theme={data.theme} onSelect={(mode) => setAppMode(mode)} />;

  const currentTheme = THEMES[data.theme];
  const modeStyle = MODE_CONFIG[appMode];
  const isStudy = appMode === AppMode.STUDY;

  return (
    <div className={`min-h-screen ${currentTheme.bg} ${currentTheme.text} ${modeStyle.font} transition-all duration-700 pb-20 lg:pb-0 lg:pl-24`}>
      {/* Sidebar (Desktop) */}
      <aside className={`fixed left-0 top-0 bottom-0 w-24 hidden lg:flex flex-col items-center py-10 ${modeStyle.sidebar} backdrop-blur-3xl border-r ${currentTheme.accent} z-50 shadow-2xl`}>
        <div className={`w-12 h-12 ${currentTheme.primary} ${modeStyle.radius} flex items-center justify-center text-white mb-12 shadow-xl hover:rotate-12 transition-transform cursor-pointer`}>
          <Sparkles size={24} />
        </div>

        <nav className="flex flex-col gap-8 flex-1">
          <NavIcon icon={LayoutDashboard} active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} theme={data.theme} appMode={appMode} label="Home" />
          <NavIcon icon={CheckSquare} active={currentView === 'tasks'} onClick={() => setCurrentView('tasks')} theme={data.theme} appMode={appMode} label="Tasks" />
          <NavIcon icon={Grid2X2} active={currentView === 'matrix'} onClick={() => setCurrentView('matrix')} theme={data.theme} appMode={appMode} label="Matrix" />
          <NavIcon icon={CalendarDays} active={currentView === 'planning'} onClick={() => setCurrentView('planning')} theme={data.theme} appMode={appMode} label="Plan" />
          <NavIcon icon={Timer} active={currentView === 'focus'} onClick={() => setCurrentView('focus')} theme={data.theme} appMode={appMode} label="Focus" />
          <NavIcon icon={BarChart3} active={currentView === 'stats'} onClick={() => setCurrentView('stats')} theme={data.theme} appMode={appMode} label="Stats" />
        </nav>

        <div className="flex flex-col gap-6 mt-auto">
          <button onClick={() => setCurrentView('settings')} className={`p-3 transition-colors ${currentView === 'settings' ? 'text-white scale-110' : 'text-slate-500 hover:text-white'}`} title="Settings">
            <Settings size={22} />
          </button>
          <button onClick={handleLogout} className="p-3 text-red-500/60 hover:text-red-500 transition-colors">
            <LogOut size={22} />
          </button>
        </div>
      </aside>

      {/* Conditional Header: Only for non-Study modes */}
      {!isStudy && (
        <header className="relative w-full overflow-hidden">
          <div className={`h-48 w-full bg-gradient-to-r ${user.bannerColor || modeStyle.headerGradient} relative overflow-hidden transition-all duration-1000`}>
            {user.level >= 5 && <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] animate-pulse opacity-20" />}
            <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent" />
          </div>

          <div className="max-w-7xl mx-auto px-6 lg:px-10 -mt-20 flex flex-col md:flex-row items-end md:items-center justify-between gap-6 relative z-10 pb-8">
            <div className="flex items-center gap-6">
              <div className="relative group">
                <div className={`w-36 h-36 ${modeStyle.radius} bg-slate-900 border-[10px] border-slate-950 overflow-hidden shadow-2xl relative`}>
                  <img src={user.avatar || `https://api.dicebear.com/7.x/avataaars/svg?seed=${user.email}`} alt="Avatar" className="w-full h-full object-cover" />
                  {user.level >= 10 && (
                    <div className="absolute top-2 right-2 bg-pink-500 text-white p-1 rounded-md scale-75 shadow-lg animate-bounce">
                        <Sparkles size={12} fill="currentColor" />
                    </div>
                  )}
                </div>
                <div className={`absolute -bottom-2 -right-2 ${currentTheme.primary} text-white w-10 h-10 ${modeStyle.radius} flex items-center justify-center font-black text-xs border-4 border-slate-950 shadow-xl`}>
                  {user.level}
                </div>
              </div>
              <div className="mb-4">
                <div className="flex items-center gap-3">
                  <h2 className="text-4xl font-black tracking-tighter drop-shadow-lg">{user.name}</h2>
                  <div className="flex gap-1">
                    {user.traits?.slice(0, 3).map(trait => (
                      <span key={trait} className={`text-[8px] px-2 py-0.5 ${modeStyle.radius} bg-white/10 text-white/80 uppercase font-black tracking-widest border border-white/5`}>{trait}</span>
                    ))}
                  </div>
                </div>
                <div className="flex items-center gap-4 mt-3">
                  <div className="w-56 h-3 bg-slate-900/50 backdrop-blur-md rounded-full overflow-hidden border border-white/5">
                    <div className={`h-full bg-gradient-to-r ${appMode === AppMode.LEISURE ? 'from-pink-500 to-indigo-500' : 'from-indigo-400 to-slate-400'} transition-all duration-1000`} style={{ width: `${(user.xp % 1000) / 10}%` }} />
                  </div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.2em] leading-none mb-0.5">Niveau {user.level}</span>
                    <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest leading-none">{user.xp % 1000} / 1000 XP</span>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-4 mb-4">
               <div className={`px-5 py-2.5 bg-slate-900/60 backdrop-blur-xl ${modeStyle.radius} border border-white/5 flex items-center gap-3 shadow-2xl`}>
                  <Trophy size={18} className={modeStyle.iconColor} />
                  <div className="flex flex-col">
                     <span className="text-[8px] font-black uppercase tracking-[0.2em] text-slate-500 leading-none">Session active</span>
                     <span className="text-xs font-black uppercase tracking-widest leading-tight">{appMode}</span>
                  </div>
               </div>
               <button 
                 onClick={() => setIsTaskModalOpen(true)}
                 className={`${currentTheme.button} ${modeStyle.radius} px-8 py-3.5 text-xs font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center gap-2`}
               >
                 <Plus size={18} strokeWidth={3} /> New Entry
               </button>
            </div>
          </div>
        </header>
      )}

      {/* Classic Study Header */}
      {isStudy && (
        <header className="max-w-7xl mx-auto px-6 lg:px-10 pt-10 pb-6 flex items-center justify-between border-b border-white/5">
          <div>
            <h1 className="text-3xl font-black tracking-tight">Espace Études</h1>
            <p className="text-sm text-slate-500 mt-1 uppercase font-bold tracking-widest">Focus & Réussite • Niveau {user.level}</p>
          </div>
          <button 
            onClick={() => setIsTaskModalOpen(true)}
            className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3 rounded-xl font-bold text-sm flex items-center gap-2 transition-all shadow-lg"
          >
            <Plus size={18} /> Nouvelle Tâche
          </button>
        </header>
      )}

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-6 lg:px-10 mt-8 pb-24">
        {currentView === 'dashboard' ? (
          <Dashboard 
            tasks={data.tasks} 
            theme={data.theme} 
            appMode={appMode}
            unavailabilities={data.unavailabilities}
            onAddTask={handleAddTask}
            onUpdateTask={handleUpdateTask}
            onAddUnavailability={(u) => {}}
            onDeleteUnavailability={(id) => {}}
          />
        ) : (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
             {currentView === 'tasks' && <TodoList tasks={data.tasks} theme={data.theme} onUpdateTask={handleUpdateTask} onDeleteTask={() => {}} onEditTask={(t) => {setEditingTask(t); setIsTaskModalOpen(true);}} onAddTask={() => setIsTaskModalOpen(true)} />}
             {currentView === 'matrix' && <EisenhowerMatrix tasks={data.tasks} theme={data.theme} onUpdateTask={handleUpdateTask} />}
             {currentView === 'focus' && <Pomodoro theme={data.theme} tasks={data.tasks} onUpdateTask={handleUpdateTask} user={user} onXpGain={(xp) => handleUpdateUser({ xp: user.xp + xp })} />}
             {currentView === 'stats' && <ProgressTracking tasks={data.tasks} theme={data.theme} />}
             {currentView === 'planning' && <SmartPlanning tasks={data.tasks} unavailabilities={data.unavailabilities} theme={data.theme} />}
             {currentView === 'settings' && <ProfileSettings user={user} onUpdateUser={handleUpdateUser} theme={data.theme} appMode={appMode} />}
          </div>
        )}
      </main>

      {isTaskModalOpen && (
        <TaskModal 
          theme={data.theme}
          task={editingTask}
          onClose={() => setIsTaskModalOpen(false)}
          onSubmit={editingTask ? (updates) => { handleUpdateTask(editingTask.id, updates); setIsTaskModalOpen(false); } : handleAddTask}
        />
      )}
    </div>
  );
};

const NavIcon = ({ icon: Icon, active, onClick, theme, appMode, label }: { 
  icon: any; 
  active: boolean; 
  onClick: () => void; 
  theme: ThemeType; 
  appMode: AppMode;
  label?: string;
}) => {
  const currentTheme = THEMES[theme];
  const modeStyle = MODE_CONFIG[appMode];
  return (
    <button 
      onClick={onClick}
      className={`group relative p-3.5 ${modeStyle.radius} transition-all duration-300 ${
        active 
        ? `${currentTheme.primary} text-white shadow-2xl scale-110` 
        : 'text-slate-500 hover:text-white hover:bg-white/5'
      }`}
    >
      <Icon size={22} strokeWidth={active ? 3 : 2} />
      {label && (
        <span className="absolute left-full ml-5 px-3 py-1.5 bg-slate-800 text-white text-[9px] rounded-lg opacity-0 group-hover:opacity-100 transition-all whitespace-nowrap pointer-events-none z-50 font-black uppercase tracking-widest border border-white/5">
          {label}
        </span>
      )}
    </button>
  );
};

export default App;

import React, { useState } from 'react';
import { Task, TaskStatus, ThemeType, AppMode, Unavailability, EisenhowerQuadrant } from '../types';
import { THEMES, MODE_CONFIG } from '../constants';
import { CheckCircle2, Clock, Sparkles, Loader2, Plus, Zap, AlertCircle } from 'lucide-react';
import { GoogleGenAI, Type } from '@google/genai';

interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  appMode: AppMode;
  unavailabilities: Unavailability[];
  onAddTask: (task: any) => void;
  onUpdateTask: (id: string, updates: any) => void;
  onAddUnavailability: (unavail: Omit<Unavailability, 'id'>) => void;
  onDeleteUnavailability: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  tasks, 
  theme, 
  appMode,
  unavailabilities, 
  onAddTask, 
  onUpdateTask,
}) => {
  const currentTheme = THEMES[theme];
  const modeStyle = MODE_CONFIG[appMode];
  const [magicInput, setMagicInput] = useState('');
  const [isMagicLoading, setIsMagicLoading] = useState(false);

  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const completedToday = tasks.filter(t => t.status === TaskStatus.DONE && t.completedAt && new Date(t.completedAt).toDateString() === new Date().toDateString()).length;

  const isStudy = appMode === AppMode.STUDY;

  const handleMagicAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!magicInput.trim()) return;
    setIsMagicLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Convertis cette demande pour le mode "${appMode}" en tâche JSON. Texte: "${magicInput}"`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              priority: { type: Type.STRING },
              difficulty: { type: Type.STRING },
              quadrant: { type: Type.STRING },
              estimatedMinutes: { type: Type.NUMBER }
            },
            required: ["title", "priority", "difficulty", "quadrant", "estimatedMinutes"]
          }
        }
      });
      const taskData = JSON.parse(response.text || '{}');
      onAddTask({ ...taskData, status: TaskStatus.TODO });
      setMagicInput('');
    } catch (e) {
      console.error(e);
    } finally {
      setIsMagicLoading(false);
    }
  };

  if (isStudy) {
    // OLD SCHOOL / CLASSIC STUDY INTERFACE
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <StatCard label="Tâches" value={pendingTasks.length.toString()} icon={Zap} color="text-emerald-400" theme={theme} appMode={appMode} />
          <StatCard label="Complétées" value={completedToday.toString()} icon={CheckCircle2} color="text-emerald-400" theme={theme} appMode={appMode} />
          <StatCard label="Temps Focus" value={`${tasks.reduce((acc, t) => acc + (t.actualMinutes || 0), 0)}m`} icon={Clock} color="text-emerald-400" theme={theme} appMode={appMode} />
          <StatCard label="Niveau" value="Actif" icon={Sparkles} color="text-emerald-400" theme={theme} appMode={appMode} />
        </div>

        <div className="bg-slate-900/40 rounded-3xl border border-white/5 p-8">
          <h3 className="text-xl font-black mb-6 flex items-center gap-3">
             <AlertCircle size={22} className="text-emerald-500" /> Vos prochaines étapes
          </h3>
          <div className="space-y-3">
            {pendingTasks.slice(0, 5).map(task => (
              <div key={task.id} className="p-4 bg-slate-950/40 rounded-xl border border-white/5 flex items-center justify-between group hover:border-emerald-500/30 transition-all">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-2 rounded-full ${task.quadrant === EisenhowerQuadrant.DO_FIRST ? 'bg-red-500' : 'bg-emerald-500'}`} />
                  <div>
                    <p className="font-bold text-sm">{task.title}</p>
                    <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest">{task.estimatedMinutes} min • {task.difficulty}</p>
                  </div>
                </div>
                <button 
                  onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })}
                  className="p-2 text-slate-500 hover:text-emerald-400 transition-colors"
                >
                  <CheckCircle2 size={20} />
                </button>
              </div>
            ))}
            {pendingTasks.length === 0 && (
              <div className="text-center py-10">
                <p className="text-slate-500 italic text-sm">Tout est fini ! Prenez une pause méritée.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // RPG / NITRO DASHBOARD
  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      <div className={`grid ${modeStyle.statsStyle} gap-6`}>
        <StatCard label="Inbox" value={pendingTasks.length.toString()} icon={Zap} color={modeStyle.iconColor} theme={theme} appMode={appMode} />
        <StatCard label="Streak" value={completedToday.toString()} icon={CheckCircle2} color="text-emerald-400" theme={theme} appMode={appMode} />
        <StatCard label="Total XP" value={`${tasks.filter(t => t.status === TaskStatus.DONE).length * 150}`} icon={Sparkles} color="text-amber-400" theme={theme} appMode={appMode} />
        <StatCard label="Dispo" value={`${unavailabilities.length}`} icon={Clock} color="text-indigo-400" theme={theme} appMode={appMode} />
      </div>

      <div className={`grid grid-cols-1 ${appMode === AppMode.EXTERNAL ? 'lg:grid-cols-1' : 'lg:grid-cols-3'} gap-10`}>
        <div className={`${appMode === AppMode.EXTERNAL ? '' : 'lg:col-span-2'} space-y-10`}>

          {modeStyle.magicAdd && (
            <div className={`${currentTheme.card} ${modeStyle.radius} ${modeStyle.glow} p-8 border ${currentTheme.accent} relative group overflow-hidden transition-all duration-500`}>
               {appMode === AppMode.LEISURE && (
                 <div className="absolute -top-10 -right-10 w-48 h-48 bg-pink-500/10 rounded-full blur-[80px] group-hover:bg-pink-500/20 transition-all duration-700" />
               )}

               <div className="flex items-center gap-4 mb-6">
                  <div className={`p-3 ${modeStyle.radius} bg-indigo-500/10 ${modeStyle.iconColor} shadow-inner`}>
                     <Sparkles size={24} />
                  </div>
                  <h3 className={`text-2xl font-black tracking-tighter`}>
                    Capture {appMode === AppMode.LEISURE ? 'Loisir' : 'Pro'}
                    <span className="ml-4 text-[9px] opacity-30 uppercase font-black tracking-[0.3em]">IA Active</span>
                  </h3>
               </div>

               <form onSubmit={handleMagicAdd} className="relative">
                  <textarea 
                     value={magicInput}
                     onChange={(e) => setMagicInput(e.target.value)}
                     placeholder={appMode === AppMode.LEISURE ? "Organiser un petit barbecue dimanche..." : "Rédaction du compte-rendu hebdomadaire."}
                     className={`w-full bg-black/30 border border-white/5 ${modeStyle.innerRadius} px-6 py-5 text-sm font-medium focus:ring-4 ring-indigo-500/10 outline-none transition-all resize-none h-32 ${appMode === AppMode.EXTERNAL ? 'font-mono uppercase text-[12px]' : ''}`}
                  />
                  <button 
                    disabled={isMagicLoading || !magicInput.trim()}
                    className={`absolute bottom-4 right-4 ${currentTheme.button} ${modeStyle.radius} px-8 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 shadow-2xl disabled:opacity-50 hover:scale-105 transition-all`}
                  >
                     {isMagicLoading ? <Loader2 size={16} className="animate-spin" /> : <Plus size={16} strokeWidth={3} />}
                     Submit
                  </button>
               </form>
            </div>
          )}

