import React, { useState, useEffect, useRef } from 'react';
import { Task, TaskStatus, ThemeType, User } from '../../types';
import { THEMES } from '../../constants';
import { Play, Pause, RotateCcw, Coffee, Brain, Bell, Target } from 'lucide-react';

interface PomodoroProps {
  theme: ThemeType;
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  user: User;
  onXpGain: (xp: number) => void;
}

const Pomodoro: React.FC<PomodoroProps> = ({ theme, tasks, onUpdateTask, user, onXpGain }) => {
  const currentTheme = THEMES[theme];
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft]);

  const handleTimerComplete = () => {
    setIsActive(false);
    if (mode === 'work') {
      if (selectedTask) {
        const task = tasks.find(t => t.id === selectedTask);
        if (task) {
          onUpdateTask(selectedTask, { actualMinutes: (task.actualMinutes || 0) + 25 });
        }
      }
      setMode('break');
      setTimeLeft(5 * 60);
    } else {
      setMode('work');
      setTimeLeft(25 * 60);
    }
  };

  const toggleTimer = () => setIsActive(!isActive);
  const resetTimer = () => {
    setIsActive(false);
    setTimeLeft(mode === 'work' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progress = (mode === 'work' ? 25 * 60 - timeLeft : 5 * 60 - timeLeft) / (mode === 'work' ? 25 * 60 : 5 * 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center space-y-8 py-10 animate-in fade-in scale-95 duration-500">
      <div className="flex gap-4 p-1 bg-white/5 backdrop-blur-md rounded-2xl border border-white/5 shadow-sm">
        <button 
          onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
          className={`flex items-center gap-2 px-6 py-2 rounded-xl text-sm font-bold transition-all ${mode === 'work' ? `${currentTheme.primary} text-white` : 'text-slate-500 hover:bg-white/5'}`}
        >
          <Brain size={18} /> Travail
        </button>
        <button 
          onClick={() => { setMode('break'); setTimeLeft(5 * 60); setIsActive(false); }}
          className={`flex items-center gap-2 px-6 py-2 rounded-xl text-sm font-bold transition-all ${mode === 'break' ? `${currentTheme.primary} text-white` : 'text-slate-500 hover:bg-white/5'}`}
        >
          <Coffee size={18} /> Pause Jeu
        </button>
      </div>

      {mode === 'work' ? (
        <>
          <div className="relative flex items-center justify-center">
            <div className="w-64 h-64 md:w-80 md:h-80 rounded-full border-[12px] border-slate-900 flex items-center justify-center relative overflow-hidden shadow-2xl">
                <div 
                  className={`absolute bottom-0 w-full transition-all duration-1000 ease-linear ${currentTheme.primary} opacity-10`} 
                  style={{ height: `${progress}%` }} 
                />
                <div className="text-6xl md:text-8xl font-black tracking-tighter tabular-nums z-10">
                    {formatTime(timeLeft)}
                </div>
            </div>
          </div>

          <div className="flex gap-6 items-center">
            <button 
              onClick={resetTimer}
              className="p-4 rounded-full bg-slate-900 text-slate-500 hover:text-white transition-all border border-white/5"
            >
              <RotateCcw size={28} />
            </button>
            <button 
              onClick={toggleTimer}
              className={`p-6 rounded-full ${currentTheme.primary} text-white shadow-xl transform transition-all active:scale-90 hover:scale-105`}
            >
              {isActive ? <Pause size={40} fill="currentColor" /> : <Play size={40} fill="currentColor" />}
            </button>
          </div>

          <div className="w-full max-w-md">
            <h3 className="text-center font-bold text-slate-500 mb-4 text-xs uppercase tracking-widest">Sur quelle tâche travailles-tu ?</h3>
            <select 
              className={`w-full bg-slate-900/50 border border-white/5 rounded-2xl px-4 py-4 text-sm focus:ring-2 ring-indigo-500 outline-none transition-all text-white`}
              value={selectedTask || ''}
              onChange={(e) => setSelectedTask(e.target.value)}
            >
              <option value="">Sélectionner une tâche...</option>
              {tasks.filter(t => t.status !== TaskStatus.DONE).map(t => (
                <option key={t.id} value={t.id}>{t.title}</option>
              ))}
            </select>
          </div>
        </>
      ) : (
        <div className="w-full max-w-2xl bg-slate-900/40 rounded-[2.5rem] border border-white/5 p-10 text-center animate-in zoom-in-95 duration-500">
           <h2 className="text-4xl font-black tracking-tighter mb-2">Mode Récré ! 🕹️</h2>
           <p className="text-slate-400 text-xs font-black uppercase tracking-widest mb-10">Cible le carré pour gagner des points de détente</p>

           <MiniGame onScore={() => onXpGain(5)} />

           <div className="mt-10 pt-10 border-t border-white/5 flex items-center justify-between">
              <div className="flex flex-col items-start">
                 <span className="text-[10px] font-black uppercase text-slate-500">Temps restant</span>
                 <span className="text-3xl font-black tabular-nums">{formatTime(timeLeft)}</span>
              </div>
              <button 
                onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
                className="bg-white/5 border border-white/10 hover:bg-white/10 px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all"
              >
                Retour au travail
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

const MiniGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const [score, setScore] = useState(0);

  const moveTarget = () => {
    setPos({
      x: Math.random() * 80 + 10,
      y: Math.random() * 80 + 10
    });
    setScore(s => s + 1);
    onScore();
  };

  return (
    <div className="relative w-full h-64 bg-slate-950/60 rounded-3xl border border-white/5 overflow-hidden">
       <div className="absolute top-4 left-6 text-[10px] font-black uppercase text-indigo-400">Score Session: {score}</div>
       <button
         onClick={moveTarget}
         className="absolute w-12 h-12 bg-indigo-500 rounded-xl shadow-lg shadow-indigo-500/40 flex items-center justify-center text-white transition-all active:scale-90 hover:scale-110"
         style={{ left: `${pos.x}%`, top: `${pos.y}%`, transform: 'translate(-50%, -50%)' }}
       >
         <Target size={24} />
       </button>
    </div>
  );
}

