import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus,
  LogOut,
  Sparkles,
  Settings,
  Trophy
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, AppMode, TaskDifficulty } from './types';
import { THEMES, MODE_CONFIG } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ModeSelector from './components/ModeSelector';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning' | 'settings';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [appMode, setAppMode] = useState<AppMode | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);

  const [activeTab, setActiveTab] = useState<View>('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');

  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      handleLogin(user);
    } else {
      setIsAuthLoading(false);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      const userData: UserData = { tasks, unavailabilities, theme };
      mockAuthService.saveUserData(currentUser.id, userData);

      const currentThemeData = THEMES[theme];
      document.body.style.backgroundColor = currentThemeData.hex;
      if (theme === 'dark' || appMode === AppMode.LEISURE) document.body.classList.add('dark');
      else document.body.classList.remove('dark');
    }
  }, [tasks, theme, unavailabilities, currentUser, appMode]);

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('evo_current_user', JSON.stringify(user));
    const userData = await mockAuthService.getUserData(user.id);
    setTasks(userData.tasks);
    setUnavailabilities(userData.unavailabilities);
    setTheme(userData.theme);
    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setAppMode(null);
    localStorage.removeItem('evo_current_user');
    setActiveTab('dashboard');
  };

  const calculateLevel = (xp: number) => Math.floor(xp / 1000) + 1;

  const gainXP = (amount: number) => {
    if (!currentUser) return;
    const newXP = currentUser.xp + amount;
    const newLevel = calculateLevel(newXP);
    const updatedUser = { ...currentUser, xp: newXP, level: newLevel };
    setCurrentUser(updatedUser);
    localStorage.setItem('evo_current_user', JSON.stringify(updatedUser));
  };

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone) {
          let xp = 100;
          if (t.difficulty === TaskDifficulty.MEDIUM) xp = 150;
          if (t.difficulty === TaskDifficulty.HARD) xp = 200;
          gainXP(xp);
        }
        return { 
          ...t, 
          ...updates, 
          completedAt: isNowDone ? Date.now() : (updates.status === TaskStatus.TODO ? undefined : t.completedAt)
        };
      }
      return t;
    }));
    setIsTaskModalOpen(false);
    setEditingTask(undefined);
  };

  if (isAuthLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-950">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-indigo-400 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="font-black text-indigo-200 uppercase tracking-[0.2em] text-xs">Evo is waking up...</p>
        </div>
      </div>
    );
  }

  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;
  if (!appMode) return <ModeSelector onSelect={setAppMode} userName={currentUser.name} />;

  const currentTheme = THEMES[theme];
  const modeStyle = MODE_CONFIG[appMode];
  const isStudy = appMode === AppMode.STUDY;

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard tasks={tasks} theme={theme} appMode={appMode} unavailabilities={unavailabilities} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} onAddUnavailability={(u) => setUnavailabilities([...unavailabilities, { ...u, id: Math.random().toString(36).substr(2, 9) }])} onDeleteUnavailability={(id) => setUnavailabilities(unavailabilities.filter(u => u.id !== id))} />;
      case 'tasks':
        return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => { setEditingTask(t); setIsTaskModalOpen(true); }} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'planning':
        return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} onXpGain={gainXP} user={currentUser} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      case 'settings':
        return <ProfileSettings user={currentUser} onUpdateUser={setCurrentUser} theme={theme} appMode={appMode} />;
      default:
        return null;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Accueil', icon: LayoutDashboard },
    { id: 'tasks', label: 'Tâches', icon: CheckSquare },
    { id: 'matrix', label: 'Priorités', icon: Grid2X2 },
    { id: 'planning', label: 'Planning IA', icon: CalendarDays },
    { id: 'focus', label: 'Focus', icon: Timer },
    { id: 'stats', label: 'Analyses', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${isStudy ? currentTheme.bg : 'bg-slate-950'} ${isStudy ? currentTheme.text : 'text-slate-100'} transition-all duration-500`}>
      {/* Sidebar */}
      <aside className={`hidden md:flex flex-col w-64 ${isStudy ? currentTheme.card : 'bg-slate-900/50 backdrop-blur-3xl'} border-r ${isStudy ? currentTheme.accent : 'border-white/5'} h-screen sticky top-0 z-50 transition-all duration-500 shadow-2xl shadow-black/5`}>
        <div className="p-8 flex items-center gap-3">
          <div className={`w-12 h-12 rounded-2xl ${isStudy ? currentTheme.primary : 'bg-indigo-600'} flex items-center justify-center text-white shadow-xl shadow-primary/20 transition-transform hover:rotate-12`}>
            <Sparkles size={28} />
          </div>
          <span className="text-3xl font-black tracking-tighter">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as View)}
              className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all duration-300 ${
                activeTab === item.id 
                ? (isStudy ? `${currentTheme.button} shadow-lg scale-[1.02]` : 'bg-indigo-600 text-white shadow-2xl shadow-indigo-600/30 scale-[1.02]') 
                : `hover:bg-black/5 dark:hover:bg-white/5 text-slate-500 font-medium`
              }`}
            >
              <item.icon size={22} />
              <span className="font-bold">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-black/5 dark:border-white/5 space-y-4">
          <button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-5 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>
            <Settings size={20} /> <span className="text-sm font-bold">Profil & XP</span>
          </button>
