          </button>
        </div>
      </aside>

      {/* Main Area */}
      <main className="flex-1 transition-all duration-500">
        {/* Conditional Header: Pro/Leisure header vs Classic Study */}
        {!isStudy ? (
           <header className="relative w-full h-48 overflow-hidden group">
