                  <div className={`w-32 h-32 rounded-full border-[6px] border-slate-950 overflow-hidden shadow-2xl bg-slate-900 ${currentUser.decoration || ''}`}>
                    <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" />
