                  <div className="absolute -bottom-1 -right-1 bg-indigo-600 text-white w-10 h-10 rounded-full border-4 border-slate-950 flex items-center justify-center font-black text-xs shadow-xl">
                    {currentUser.level}
                  </div>
                </div>
                <div className="mb-4">
                  <h1 className="text-4xl font-black tracking-tighter text-white drop-shadow-md">{currentUser.name}</h1>
                  <div className="flex items-center gap-4 mt-2">
                    <div className="w-48 h-2 bg-black/40 rounded-full overflow-hidden backdrop-blur-md">
                      <div className="h-full bg-gradient-to-r from-indigo-400 to-pink-500 transition-all duration-1000" style={{ width: `${(currentUser.xp % 1000) / 10}%` }} />
                    </div>
                    <span className="text-[10px] font-black uppercase text-indigo-400 tracking-widest">{currentUser.xp % 1000} / 1000 XP</span>
                  </div>
                </div>
              </div>
           </header>
        ) : (
          <header className="px-6 md:px-10 pt-10 pb-6 border-b border-black/5 dark:border-white/5 flex justify-between items-center">
             <div>
               <h1 className="text-3xl font-black tracking-tighter">Espace d'Études</h1>
               <p className="text-slate-400 text-sm font-bold uppercase tracking-widest mt-1">Focus & Productivité Classique</p>
             </div>
             <button onClick={() => setIsTaskModalOpen(true)} className="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3 rounded-xl font-bold transition-all shadow-lg flex items-center gap-2">
               <Plus size={20} /> Nouvelle Tâche
             </button>
          </header>
        )}

        <div className="p-4 md:p-10 pb-24 md:pb-10 max-w-7xl mx-auto w-full">
          {renderContent()}
        </div>
      </main>

      {isTaskModalOpen && (
        <TaskModal 
          theme={theme}
          task={editingTask}
          onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }}
          onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask}
        />
      )}
    </div>
  );
};

