          <StatCard label="Complétées" value={completedToday.toString()} icon={CheckCircle2} color="text-emerald-400" theme={theme} isStudy />
          <StatCard label="Temps Focus" value={`${tasks.reduce((acc, t) => acc + (t.actualMinutes || 0), 0)}m`} icon={Clock} color="text-emerald-400" theme={theme} isStudy />
          <StatCard label="Focus Score" value={`${tasks.length > 0 ? Math.round((tasks.filter(t => t.status === TaskStatus.DONE).length / tasks.length) * 100) : 0}%`} icon={Sparkles} color="text-emerald-400" theme={theme} isStudy />
        </div>

        <div className="bg-white dark:bg-slate-900/40 rounded-3xl border border-black/5 dark:border-white/5 p-8 shadow-sm">
          <h3 className="text-xl font-black mb-6 flex items-center gap-3">
             <AlertCircle size={22} className="text-emerald-500" /> Prochaines priorités
          </h3>
          <div className="space-y-3">
            {pendingTasks.slice(0, 5).map(task => (
              <div key={task.id} className="p-4 bg-slate-50 dark:bg-slate-950/40 rounded-xl border border-black/5 flex items-center justify-between group hover:border-emerald-500/30 transition-all">
                <div className="flex items-center gap-4">
                  <div className={`w-2 h-2 rounded-full ${task.quadrant === EisenhowerQuadrant.DO_FIRST ? 'bg-red-500' : 'bg-emerald-500'}`} />
                  <div>
                    <p className="font-bold text-sm">{task.title}</p>
                    <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest">{task.estimatedMinutes} min • {task.difficulty}</p>
                  </div>
                </div>
                <button onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })} className="p-2 text-slate-400 hover:text-emerald-500 transition-colors">
                  <CheckCircle2 size={20} />
                </button>
              </div>
            ))}
            {pendingTasks.length === 0 && <p className="text-center py-10 text-slate-400 italic">Tout est à jour !</p>}
          </div>
        </div>
      </div>
    );
  }

  // RPG / LEISURE INTERFACE
  return (
    <div className="space-y-10 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard label="Quêtes en cours" value={pendingTasks.length.toString()} icon={Zap} color="text-indigo-400" theme={theme} />
        <StatCard label="XP Gagnée (J)" value={(completedToday * 150).toString()} icon={Sparkles} color="text-amber-400" theme={theme} />
        <StatCard label="Temps de jeu débloqué" value={`${Math.floor(completedToday * 15)} min`} icon={Clock} color="text-pink-400" theme={theme} />
        <StatCard label="Complétion" value={`${tasks.length > 0 ? Math.round((tasks.filter(t => t.status === TaskStatus.DONE).length / tasks.length) * 100) : 0}%`} icon={CheckCircle2} color="text-emerald-400" theme={theme} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-10">
          <div className="bg-slate-900/40 rounded-[2.5rem] border border-white/5 p-10 backdrop-blur-3xl shadow-2xl relative overflow-hidden group">
            <div className="absolute -top-24 -right-24 w-64 h-64 bg-indigo-600/10 rounded-full blur-[100px] transition-all group-hover:bg-indigo-600/20" />
            <h3 className="text-2xl font-black mb-8 flex items-center gap-3"><Zap size={24} className="text-indigo-500" /> Journal de Quêtes</h3>
            <div className="space-y-4">
              {pendingTasks.slice(0, 4).map(task => (
                <div key={task.id} className="p-6 bg-slate-950/60 rounded-3xl border border-white/5 flex items-center justify-between group/task hover:border-indigo-500/30 transition-all">
                  <div className="flex items-center gap-6">
                    <div className={`w-12 h-12 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-400`}>
                      <Plus size={24} />
