                    <div>
                      <h4 className="font-bold text-lg">{task.title}</h4>
                      <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest mt-1">XP: {task.difficulty === 'hard' ? 200 : task.difficulty === 'medium' ? 150 : 100}</p>
                    </div>
                  </div>
                  <button onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })} className="bg-indigo-600 hover:bg-indigo-500 text-white p-3 rounded-2xl shadow-xl transition-all scale-0 group-hover/task:scale-100 opacity-0 group-hover/task:opacity-100">
                    <CheckCircle2 size={24} />
                  </button>
                </div>
