        <div className="space-y-8">
           <div className="bg-slate-900/40 rounded-[2.5rem] border border-white/5 p-8 backdrop-blur-3xl shadow-2xl">
              <h4 className="text-xs font-black uppercase tracking-widest text-slate-500 mb-6 flex items-center gap-2"><Clock size={16} /> Focus Bonus</h4>
              <div className="text-center py-6">
                <div className="text-5xl font-black tracking-tighter text-indigo-400 tabular-nums">25:00</div>
                <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest mt-2">Prêt pour la prochaine session ?</p>
                <button className="mt-8 w-full bg-indigo-600 hover:bg-indigo-500 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl shadow-indigo-600/20">Lancer la session</button>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; icon: any; color: string; theme: ThemeType; isStudy?: boolean }> = ({ label, value, icon: Icon, color, theme, isStudy }) => {
