import React, { useState, useEffect, useRef } from 'react';
import { Task, TaskStatus, ThemeType, User } from '../../types';
import { THEMES } from '../../constants';
import { Play, Pause, RotateCcw, Coffee, Brain, Target, Zap } from 'lucide-react';

interface PomodoroProps {
  theme: ThemeType;
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  onXpGain: (amount: number) => void;
  user: User;
}

const Pomodoro: React.FC<PomodoroProps> = ({ theme, tasks, onUpdateTask, onXpGain, user }) => {
  const currentTheme = THEMES[theme];
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);
  const [gameScore, setGameScore] = useState(0);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [isActive, timeLeft]);

  const handleTimerComplete = () => {
    setIsActive(false);
    if (mode === 'work') {
      if (selectedTask) {
        const task = tasks.find(t => t.id === selectedTask);
        if (task) onUpdateTask(selectedTask, { actualMinutes: (task.actualMinutes || 0) + 25 });
      }
      onXpGain(100); // Bonus session complète
      setMode('break');
      setTimeLeft(5 * 60);
      setGameScore(0);
    } else {
      setMode('work');
      setTimeLeft(25 * 60);
    }
  };

  const toggleTimer = () => setIsActive(!isActive);
  const resetTimer = () => {
    setIsActive(false);
    setTimeLeft(mode === 'work' ? 25 * 60 : 5 * 60);
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progress = (mode === 'work' ? 25 * 60 - timeLeft : 5 * 60 - timeLeft) / (mode === 'work' ? 25 * 60 : 5 * 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center space-y-8 py-10 animate-in fade-in duration-500">
      <div className="flex gap-4 p-1.5 bg-slate-200/50 dark:bg-slate-800 rounded-2xl border border-black/5">
        <button 
          onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-black transition-all ${mode === 'work' ? `${currentTheme.primary} text-white shadow-md` : 'text-slate-500 hover:bg-black/5'}`}
        >
          <Brain size={18} /> Travail
        </button>
        <button 
          onClick={() => { setMode('break'); setTimeLeft(5 * 60); setIsActive(false); }}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-black transition-all ${mode === 'break' ? `bg-indigo-600 text-white shadow-md` : 'text-slate-500 hover:bg-black/5'}`}
        >
          <Coffee size={18} /> Pause Jeu
        </button>
      </div>

      {mode === 'work' ? (
        <div className="flex flex-col items-center space-y-10 w-full">
          <div className="relative flex items-center justify-center">
            <div className="w-64 h-64 md:w-80 md:h-80 rounded-full border-[10px] border-slate-200 dark:border-slate-800 flex items-center justify-center relative overflow-hidden bg-white dark:bg-slate-900 shadow-xl">
                <div className={`absolute bottom-0 w-full transition-all duration-1000 ease-linear ${currentTheme.primary} opacity-10`} style={{ height: `${progress}%` }} />
                <div className="text-6xl md:text-8xl font-black tracking-tighter tabular-nums z-10">{formatTime(timeLeft)}</div>
            </div>
          </div>

          <div className="flex gap-6 items-center">
            <button onClick={resetTimer} className="p-4 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-400 hover:text-slate-600 transition-all border border-black/5"><RotateCcw size={28} /></button>
            <button onClick={toggleTimer} className={`p-6 rounded-full ${currentTheme.primary} text-white shadow-xl transform transition-all active:scale-90 hover:scale-105`}>
              {isActive ? <Pause size={44} fill="currentColor" /> : <Play size={44} fill="currentColor" className="ml-1" />}
            </button>
          </div>

          <div className="w-full max-w-md">
            <h3 className="text-center font-black text-slate-400 mb-4 text-[10px] uppercase tracking-[0.2em]">Cible de focus</h3>
            <select className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl px-5 py-4 text-sm font-bold focus:ring-4 ring-indigo-500/10 outline-none transition-all shadow-sm" value={selectedTask || ''} onChange={(e) => setSelectedTask(e.target.value)}>
              <option value="">Sélectionner une quête...</option>
              {tasks.filter(t => t.status !== TaskStatus.DONE).map(t => <option key={t.id} value={t.id}>{t.title}</option>)}
            </select>
          </div>
        </div>
      ) : (
        <div className="w-full max-w-2xl bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 p-10 text-center shadow-2xl animate-in zoom-in-95 duration-500">
          <h2 className="text-4xl font-black tracking-tighter mb-2">Evo-Clicker 🕹️</h2>
          <p className="text-slate-500 text-xs font-black uppercase tracking-widest mb-10">Récolte un maximum d'XP pendant ta pause !</p>

          <MiniGame onScore={() => { setGameScore(s => s + 1); onXpGain(5); }} />

          <div className="mt-10 flex items-center justify-between border-t border-slate-100 pt-10">
            <div className="text-left">
              <span className="text-[10px] font-black uppercase text-slate-400">Temps de pause</span>
              <p className="text-3xl font-black tabular-nums">{formatTime(timeLeft)}</p>
            </div>
            <div className="text-right">
              <span className="text-[10px] font-black uppercase text-slate-400">XP récoltée</span>
              <p className="text-3xl font-black text-indigo-500 tabular-nums">+{gameScore * 5}</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const MiniGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const move = () => {
    setPos({ x: Math.random() * 80 + 10, y: Math.random() * 80 + 10 });
    onScore();
  };
  return (
    <div className="relative w-full h-64 bg-slate-50 dark:bg-slate-950 rounded-[2rem] border border-slate-100 dark:border-slate-800 overflow-hidden shadow-inner">
      <button 
        onClick={move} 
        className="absolute w-14 h-14 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-600/30 flex items-center justify-center text-white transition-all active:scale-90 hover:scale-110" 
        style={{ left: `${pos.x}%`, top: `${pos.y}%`, transform: 'translate(-50%, -50%)' }}
      >
        <Zap size={28} fill="white" />
      </button>
    </div>
  );
};

export default Pomodoro;

