            <input
              required
              type={showPassword ? "text" : "password"}
              placeholder="MOT DE PASSE"
              value={formData.password}
              onChange={(e) => setFormData({...formData, password: e.target.value})}
              className="w-full bg-slate-950 border border-white/5 rounded-2xl pl-12 pr-12 py-5 text-sm font-bold uppercase tracking-widest focus:ring-4 ring-emerald-500/10 outline-none transition-all text-white placeholder:text-slate-700"
            />
            <button 
              type="button" 
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-600 hover:text-white transition-colors"
            >
              {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
            </button>
          </div>

          <button
            disabled={isLoading}
            className="w-full bg-emerald-600 text-white font-black py-6 rounded-2xl shadow-2xl shadow-emerald-600/30 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isLoading ? <Loader2 className="animate-spin" size={20} /> : <ArrowRight size={20} strokeWidth={3} />}
            <span className="uppercase text-sm tracking-[0.2em]">{isLogin ? 'Accéder au Compagnon' : 'Créer mon Profil'}</span>
          </button>
        </form>

        <div className="mt-8 text-center">
          <button
            onClick={() => setIsLogin(!isLogin)}
            className="text-[10px] font-black text-slate-500 hover:text-white transition-colors uppercase tracking-[0.2em]"
          >
            {isLogin ? "Nouveau ici ? Créer un profil" : "Déjà membre ? Se connecter"}
          </button>
        </div>
      </div>
    </div>
  );
};

