import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus,
  LogOut,
  Sparkles,
  Settings,
  Trophy
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, TaskDifficulty } from './types';
import { THEMES } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning' | 'settings';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);

  const [activeTab, setActiveTab] = useState<View>('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');

  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      handleLogin(user);
    } else {
      setIsAuthLoading(false);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      const userData: UserData = { tasks, unavailabilities, theme };
      mockAuthService.saveUserData(currentUser.id, userData);

      const currentThemeData = THEMES[theme];
      document.body.style.backgroundColor = currentThemeData.hex;
      if (theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [tasks, theme, unavailabilities, currentUser]);

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('evo_current_user', JSON.stringify(user));
    const userData = await mockAuthService.getUserData(user.id);
    setTasks(userData.tasks);
    setUnavailabilities(userData.unavailabilities);
    setTheme(userData.theme);
    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('evo_current_user');
    setActiveTab('dashboard');
  };

  const calculateLevel = (xp: number) => Math.floor(xp / 1000) + 1;

  const gainXP = (amount: number) => {
    if (!currentUser) return;
    const newXP = currentUser.xp + amount;
    const newLevel = calculateLevel(newXP);
    const updatedUser = { ...currentUser, xp: newXP, level: newLevel };
    setCurrentUser(updatedUser);
    localStorage.setItem('evo_current_user', JSON.stringify(updatedUser));
  };

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone) {
          let xp = 100;
          if (t.difficulty === TaskDifficulty.MEDIUM) xp = 150;
          if (t.difficulty === TaskDifficulty.HARD) xp = 200;
          gainXP(xp);
        }
        return { 
          ...t, 
          ...updates, 
          completedAt: isNowDone ? Date.now() : (updates.status === TaskStatus.TODO ? undefined : t.completedAt)
        };
      }
      return t;
    }));
    setIsTaskModalOpen(false);
    setEditingTask(undefined);
  };

  if (isAuthLoading) return null;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  const currentTheme = THEMES[theme];

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard tasks={tasks} theme={theme} unavailabilities={unavailabilities} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} onAddUnavailability={() => {}} onDeleteUnavailability={() => {}} />;
      case 'tasks':
        return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => { setEditingTask(t); setIsTaskModalOpen(true); }} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'planning':
        return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} onXpGain={gainXP} user={currentUser} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      case 'settings':
        return <ProfileSettings user={currentUser} onUpdateUser={setCurrentUser} theme={theme} onThemeChange={setTheme} />;
      default:
        return null;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Accueil', icon: LayoutDashboard },
    { id: 'tasks', label: 'Tâches', icon: CheckSquare },
    { id: 'matrix', label: 'Priorités', icon: Grid2X2 },
    { id: 'planning', label: 'IA Planning', icon: CalendarDays },
    { id: 'focus', label: 'Timer Focus', icon: Timer },
    { id: 'stats', label: 'Progression', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-all duration-500`}>
      {/* Sidebar */}
      <aside className={`hidden md:flex flex-col w-64 ${currentTheme.card} border-r ${currentTheme.border} h-screen sticky top-0 z-50 shadow-sm transition-colors duration-500`}>
        <div className="p-8 flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg`}>
            <Sparkles size={24} />
          </div>
          <span className="text-2xl font-black tracking-tight">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as View)}
              className={`w-full flex items-center gap-3 px-5 py-3.5 rounded-xl transition-all ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-md` 
                : `text-slate-500 hover:bg-black/5 dark:hover:bg-white/5 font-semibold`
              }`}
            >
              <item.icon size={20} />
              <span className="text-sm">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t ${currentTheme.border} space-y-2">
          <button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-5 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-black/5'}`}>
            <Settings size={18} /> <span className="text-xs font-bold uppercase tracking-widest">Profil</span>
          </button>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-5 py-3 rounded-xl text-red-500 hover:bg-red-50 transition-all">
            <LogOut size={18} /> <span className="text-xs font-bold uppercase tracking-widest">Déconnexion</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-x-hidden relative">
        {/* Profile Header (Nitro Style) */}
        <header className="relative w-full h-48 overflow-hidden group">
           <div className={`absolute inset-0 bg-gradient-to-r ${currentUser.bannerColor} transition-all duration-700`}>
             <div className="absolute inset-0 bg-black/20" />
           </div>
           <div className="max-w-7xl mx-auto px-6 md:px-10 flex items-end h-full pb-8 gap-6 relative z-10">
              <div className="relative">
                 <div className={`w-32 h-32 rounded-full border-[6px] border-white dark:border-slate-900 overflow-hidden shadow-2xl bg-slate-200 transition-all ${currentUser.decoration || ''}`}>
                    <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" />
                 </div>
                 <div className={`absolute -bottom-1 -right-1 ${currentTheme.primary} text-white w-10 h-10 rounded-full border-4 border-white dark:border-slate-900 flex items-center justify-center font-black text-xs shadow-lg`}>
                    {currentUser.level}
                 </div>
              </div>
              <div className="mb-2 flex-1">
                 <h1 className="text-4xl font-black text-white drop-shadow-lg tracking-tight mb-2">{currentUser.name}</h1>
                 <div className="flex items-center gap-4">
                    <div className="flex-1 max-w-xs h-2.5 bg-black/30 rounded-full overflow-hidden backdrop-blur-sm">
                       <div className="h-full bg-white shadow-[0_0_10px_white] transition-all duration-1000" style={{ width: `${(currentUser.xp % 1000) / 10}%` }} />
                    </div>
                    <span className="text-[10px] font-black uppercase text-white tracking-widest drop-shadow-sm">{currentUser.xp % 1000} / 1000 XP</span>
                 </div>
              </div>
              <button 
                onClick={() => setIsTaskModalOpen(true)}
                className="hidden lg:flex items-center gap-2 bg-white/20 hover:bg-white/30 backdrop-blur-md text-white px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest border border-white/30 transition-all active:scale-95 shadow-xl"
              >
                <Plus size={18} strokeWidth={3} /> Nouvelle Quête
              </button>
           </div>
        </header>

        <div className="p-6 md:p-10 max-w-7xl mx-auto w-full">
           {renderContent()}
        </div>

        {/* Floating Add Button for Mobile */}
        <button 
          onClick={() => setIsTaskModalOpen(true)}
          className="lg:hidden fixed bottom-6 right-6 w-16 h-16 rounded-full bg-indigo-600 text-white shadow-2xl flex items-center justify-center z-50 active:scale-90 transition-transform"
        >
          <Plus size={32} strokeWidth={3} />
        </button>
      </main>

      {isTaskModalOpen && (
        <TaskModal 
          theme={theme}
          task={editingTask}
          onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }}
          onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask}
        />
      )}
    </div>
  );
};

export default App;

