        <StatCard label="XP Accumulée" value={`${tasks.filter(t => t.status === TaskStatus.DONE).reduce((acc, t) => acc + (t.difficulty === 'hard' ? 200 : t.difficulty === 'medium' ? 150 : 100), 0)}`} icon={Sparkles} color="text-amber-500" theme={theme} />
