                      <div className={`w-3 h-3 rounded-full shadow-lg ${task.quadrant === EisenhowerQuadrant.DO_FIRST ? 'bg-red-500 shadow-red-500/20' : 'bg-emerald-500 shadow-emerald-500/20'}`} />
