                        <div className="flex items-center gap-3">
                           <span className="text-[10px] text-slate-400 uppercase font-black tracking-widest">{task.estimatedMinutes} min</span>
                           <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${task.difficulty === 'hard' ? 'bg-rose-100 text-rose-600' : task.difficulty === 'medium' ? 'bg-amber-100 text-amber-600' : 'bg-emerald-100 text-emerald-600'}`}>{task.difficulty}</span>
