import React, { useState } from 'react';
import { Task, TaskPriority, TaskDifficulty, EisenhowerQuadrant, TaskStatus, ThemeType } from '../../types';
import { THEMES } from '../../constants';
import { X, Check } from 'lucide-react';

interface TaskModalProps {
  theme: ThemeType;
  task?: Task;
  onClose: () => void;
  onSubmit: (taskData: any) => void;
}

const TaskModal: React.FC<TaskModalProps> = ({ theme, task, onClose, onSubmit }) => {
  const currentTheme = THEMES[theme];
  const [title, setTitle] = useState(task?.title || '');
  const [priority, setPriority] = useState<TaskPriority>(task?.priority || TaskPriority.MEDIUM);
  const [difficulty, setDifficulty] = useState<TaskDifficulty>(task?.difficulty || TaskDifficulty.MEDIUM);
  const [quadrant, setQuadrant] = useState<EisenhowerQuadrant>(task?.quadrant || EisenhowerQuadrant.DO_FIRST);
  const [estimatedMinutes, setEstimatedMinutes] = useState(task?.estimatedMinutes || 30);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onSubmit({
      title,
      priority,
      difficulty,
      quadrant,
      estimatedMinutes,
      status: task?.status || TaskStatus.TODO,
    });
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md animate-in fade-in duration-200">
      <div className={`${currentTheme.card} w-full max-w-md rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border ${currentTheme.border}`}>
        <div className="p-8 border-b border-black/5 flex justify-between items-center">
          <h2 className="text-2xl font-black tracking-tight">{task ? 'Éditer la quête' : 'Nouvelle Quête'}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors">
            <X size={24} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-8">
          <div className="space-y-3">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Intitulé</label>
            <input 
              autoFocus
              type="text" 
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Ex: Révisions Mathématiques..."
              className={`w-full ${currentTheme.input} border-none rounded-2xl px-6 py-5 text-sm font-bold focus:ring-4 ring-indigo-500/20 transition-all outline-none shadow-inner`}
            />
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-3">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Difficulté</label>
              <div className="flex bg-slate-100 dark:bg-slate-800 p-1.5 rounded-2xl">
                {Object.values(TaskDifficulty).map((d) => (
                  <button
                    key={d}
                    type="button"
                    onClick={() => setDifficulty(d)}
                    className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${difficulty === d ? 'bg-white dark:bg-slate-700 shadow-md text-indigo-600 dark:text-indigo-400' : 'text-slate-500'}`}
                  >
                    {d === 'easy' ? 'Facile' : d === 'medium' ? 'Moyen' : 'Dur'}
                  </button>
                ))}
              </div>
            </div>
            <div className="space-y-3">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Minutes</label>
              <input 
                type="number" 
                value={estimatedMinutes}
                onChange={(e) => setEstimatedMinutes(parseInt(e.target.value))}
                className={`w-full ${currentTheme.input} border-none rounded-2xl px-6 py-4 text-sm font-bold focus:ring-4 ring-indigo-500/20 transition-all outline-none shadow-inner`}
              />
            </div>
          </div>

          <div className="space-y-3">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Priorité Eisenhower</label>
            <select 
              value={quadrant}
              onChange={(e) => setQuadrant(e.target.value as EisenhowerQuadrant)}
              className={`w-full ${currentTheme.input} border-none rounded-2xl px-6 py-4 text-sm font-bold focus:ring-4 ring-indigo-500/20 outline-none shadow-inner`}
            >
              <option value={EisenhowerQuadrant.DO_FIRST}>🔴 Urgent & Important</option>
              <option value={EisenhowerQuadrant.SCHEDULE}>🔵 Important (Non-urgent)</option>
              <option value={EisenhowerQuadrant.DELEGATE}>🟡 Urgent (Non-important)</option>
              <option value={EisenhowerQuadrant.ELIMINATE}>⚪ Ni l'un ni l'autre</option>
            </select>
          </div>

          <button 
            type="submit" 
            className={`w-full ${currentTheme.button} py-5 rounded-[1.5rem] font-black text-sm uppercase tracking-widest shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all`}
          >
            <Check size={20} strokeWidth={3} /> {task ? 'Sauvegarder' : 'Ajouter au Journal'}
          </button>
        </form>
      </div>
    </div>
  );
};

