interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  unavailabilities: any[];
  onAddTask: () => void;
  onUpdateTask: (id: string, updates: any) => void;
  onAddUnavailability: (unavail: any) => void;
  onDeleteUnavailability: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  tasks, 
  theme, 
  onUpdateTask,
  onAddTask
}) => {
  const currentTheme = THEMES[theme];
  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const completedToday = tasks.filter(t => t.status === TaskStatus.DONE && t.completedAt && new Date(t.completedAt).toDateString() === new Date().toDateString()).length;
  const totalFocusMinutes = tasks.reduce((acc, t) => acc + (t.actualMinutes || 0), 0);

  return (
    <div className="space-y-12">
      {/* Statistiques Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard label="Journal de Quêtes" value={pendingTasks.length.toString()} icon={Zap} color="text-indigo-500" theme={theme} />
        <StatCard label="Succès (Aujourd'hui)" value={completedToday.toString()} icon={CheckCircle2} color="text-emerald-500" theme={theme} />
        <StatCard label="Total Focus" value={`${Math.floor(totalFocusMinutes / 60)}h ${totalFocusMinutes % 60}m`} icon={Clock} color="text-blue-500" theme={theme} />
        <StatCard label="Prestige XP" value={`${tasks.filter(t => t.status === TaskStatus.DONE).reduce((acc, t) => acc + (t.difficulty === 'hard' ? 200 : t.difficulty === 'medium' ? 150 : 100), 0)}`} icon={Sparkles} color="text-amber-500" theme={theme} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-8">
          <div className={`${currentTheme.card} ${currentTheme.radius} border ${currentTheme.border} p-10 ${currentTheme.shadow} transition-all duration-500`}>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-3xl font-black flex items-center gap-4">
                 <AlertCircle size={28} className={currentTheme.secondary} /> Objectifs Prioritaires
              </h3>
              <button 
                onClick={onAddTask}
                className={`p-3 bg-slate-100 dark:bg-slate-800 rounded-2xl text-slate-500 hover:text-indigo-500 transition-all ${currentTheme.shadow}`}
              >
                <Plus size={24} />
              </button>
            </div>

            <div className="space-y-4">
              {pendingTasks.length > 0 ? (
                pendingTasks.slice(0, 5).map(task => (
                  <div key={task.id} className={`p-6 bg-slate-50 dark:bg-slate-800/60 ${currentTheme.radius} border border-black/5 flex items-center justify-between group hover:scale-[1.01] transition-all`}>
                    <div className="flex items-center gap-6">
                      <div className={`w-4 h-4 rounded-full shadow-[0_0_15px_rgba(0,0,0,0.2)] ${task.quadrant === EisenhowerQuadrant.DO_FIRST ? 'bg-red-500' : 'bg-emerald-500'}`} />
                      <div>
                        <p className="font-bold text-lg leading-tight mb-2">{task.title}</p>
                        <div className="flex items-center gap-4">
                           <span className="text-xs text-slate-400 uppercase font-black tracking-widest">{task.estimatedMinutes} min estimé</span>
                           <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-lg ${task.difficulty === 'hard' ? 'bg-rose-500/10 text-rose-500' : task.difficulty === 'medium' ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>{task.difficulty}</span>
                        </div>
                      </div>
                    </div>
                    <button 
                      onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })} 
                      className={`p-4 bg-white dark:bg-slate-900 text-slate-200 hover:text-emerald-500 rounded-2xl shadow-md border border-black/5 transition-all active:scale-90`}
                    >
                      <CheckCircle2 size={28} />
                    </button>
                  </div>
                ))
              ) : (
                <div className="text-center py-24 opacity-30">
                   <Zap size={64} className="mx-auto mb-6 text-slate-400" />
                   <p className="font-black text-xl text-slate-500 uppercase tracking-widest">Toutes les quêtes sont terminées ! ✨</p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="space-y-8">
           <div className={`${currentTheme.card} ${currentTheme.radius} border ${currentTheme.border} p-10 text-center ${currentTheme.shadow} transition-all duration-500`}>
              <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-10 flex items-center justify-center gap-3">
                <Clock size={20} /> SESSION RAPIDE
              </h4>
              <div className="text-7xl font-black tracking-tighter tabular-nums mb-6 text-slate-900 dark:text-white drop-shadow-xl">25:00</div>
              <p className="text-sm font-bold text-slate-500 mb-10 italic leading-relaxed">Boost ton XP en complétant une session maintenant !</p>
              <button className={`${currentTheme.button} w-full py-6 ${currentTheme.radius} font-black text-xs uppercase tracking-[0.25em] shadow-xl active:scale-95 transition-all`}>LANCER FOCUS</button>
           </div>
        </div>
      </div>
