import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  CheckSquare, 
  Grid2X2, 
  Timer, 
  BarChart3, 
  CalendarDays,
  Plus,
  LogOut,
  Sparkles,
  Settings,
  Palette
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, TaskDifficulty } from './types';
import { THEMES } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning' | 'settings';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<View>('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      handleLogin(user);
    } else {
      setIsAuthLoading(false);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      const userData: UserData = { tasks, unavailabilities, theme };
      mockAuthService.saveUserData(currentUser.id, userData);

      const currentThemeData = THEMES[theme];
      document.body.style.backgroundColor = currentThemeData.bg.includes('black') ? '#000' : '#f8fafc';
      if (theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [tasks, theme, unavailabilities, currentUser]);

  const handleLogin = async (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('evo_current_user', JSON.stringify(user));
    const userData = await mockAuthService.getUserData(user.id);
    setTasks(userData.tasks);
    setUnavailabilities(userData.unavailabilities);
    setTheme(userData.theme);
    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('evo_current_user');
    setActiveTab('dashboard');
  };

  const calculateLevel = (xp: number) => Math.floor(xp / 1000) + 1;

  const gainXP = (amount: number) => {
    if (!currentUser) return;
    const newXP = currentUser.xp + amount;
    const newLevel = calculateLevel(newXP);
    const updatedUser = { ...currentUser, xp: newXP, level: newLevel };
    setCurrentUser(updatedUser);
    localStorage.setItem('evo_current_user', JSON.stringify(updatedUser));
  };

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone) {
          let xp = t.difficulty === TaskDifficulty.HARD ? 200 : t.difficulty === TaskDifficulty.MEDIUM ? 150 : 100;
          gainXP(xp);
        }
        return { 
          ...t, 
          ...updates, 
          completedAt: isNowDone ? Date.now() : (updates.status === TaskStatus.TODO ? undefined : t.completedAt)
        };
      }
      return t;
    }));
  };

  // Fix: Added missing deleteTask handler
  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  // Fix: Added missing updateUser handler
  const updateUser = (updates: User) => {
    setCurrentUser(updates);
    localStorage.setItem('evo_current_user', JSON.stringify(updates));
  };

  // Fix: Added missing unavailability handlers
  const addUnavailability = (unavail: any) => {
    const newUnavail = {
      ...unavail,
      id: Math.random().toString(36).substr(2, 9)
    };
    setUnavailabilities([...unavailabilities, newUnavail]);
  };

  const deleteUnavailability = (id: string) => {
    setUnavailabilities(unavailabilities.filter(u => u.id !== id));
  };

  // Fix: Implemented missing renderContent function
  const renderContent = () => {
    if (!currentUser) return null;

    switch (activeTab) {
      case 'dashboard':
        return (
          <Dashboard 
            tasks={tasks} 
            theme={theme} 
            unavailabilities={unavailabilities}
            onAddTask={() => setIsTaskModalOpen(true)}
            onUpdateTask={updateTask}
            onAddUnavailability={addUnavailability}
            onDeleteUnavailability={deleteUnavailability}
          />
        );
      case 'tasks':
        return (
          <TodoList 
            tasks={tasks} 
            onUpdateTask={updateTask} 
            onDeleteTask={deleteTask}
            onEditTask={(task) => {
              setEditingTask(task);
              setIsTaskModalOpen(true);
            }}
            onAddTask={() => setIsTaskModalOpen(true)}
            theme={theme}
          />
        );
      case 'matrix':
        return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'focus':
        return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} onXpGain={gainXP} user={currentUser} />;
      case 'stats':
        return <ProgressTracking tasks={tasks} theme={theme} />;
      case 'planning':
        return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'settings':
        return (
          <ProfileSettings 
            user={currentUser} 
            onUpdateUser={updateUser} 
            theme={theme} 
            onThemeChange={setTheme} 
          />
        );
      default:
        return null;
    }
  };

  if (isAuthLoading) return null;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  const currentTheme = THEMES[theme];

  const navItems = [
    { id: 'dashboard', label: 'Accueil', icon: LayoutDashboard },
    { id: 'tasks', label: 'Quêtes', icon: CheckSquare },
    { id: 'matrix', label: 'Priorités', icon: Grid2X2 },
    { id: 'planning', label: 'IA Planning', icon: CalendarDays },
    { id: 'focus', label: 'Timer Focus', icon: Timer },
    { id: 'stats', label: 'Progression', icon: BarChart3 },
  ];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-all duration-500`}>
      {/* Sidebar */}
      <aside className={`hidden md:flex flex-col w-72 ${currentTheme.card} border-r ${currentTheme.border} h-screen sticky top-0 z-50 shadow-lg transition-colors duration-500`}>
        <div className="p-8 flex items-center gap-4">
          <div className={`w-12 h-12 ${currentTheme.radius} ${currentTheme.primary} flex items-center justify-center text-white shadow-xl ${currentTheme.glow}`}>
            <Sparkles size={28} />
          </div>
          <span className="text-3xl font-black tracking-tighter">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as View)}
              className={`w-full flex items-center gap-3 px-5 py-4 ${currentTheme.radius} transition-all ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-xl ${currentTheme.glow}` 
                : `text-slate-500 hover:bg-black/5 dark:hover:bg-white/5 font-bold`
              }`}
            >
              <item.icon size={22} />
              <span className="text-sm uppercase tracking-widest">{item.label}</span>
            </button>
          ))}

          <div className="pt-6 pb-2 px-5">
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Changer de Thème</span>
          </div>
          <div className="px-4 grid grid-cols-5 gap-2">
            {(Object.keys(THEMES) as ThemeType[]).map((t) => (
              <button 
                key={t}
                onClick={() => setTheme(t)}
                className={`h-10 rounded-lg border-2 transition-all ${theme === t ? 'border-white ring-2 ring-indigo-500 scale-110' : 'border-transparent opacity-60 hover:opacity-100'}`}
                style={{ backgroundColor: THEMES[t].id === 'dark' ? '#1e293b' : THEMES[t].primary.replace('bg-', '') }}
              />
            ))}
          </div>
        </nav>

        <div className="p-6 border-t ${currentTheme.border} space-y-3">
          <button onClick={() => setActiveTab('settings')} className={`w-full flex items-center gap-3 px-5 py-3 ${currentTheme.radius} transition-all ${activeTab === 'settings' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-black/5'}`}>
            <Settings size={20} /> <span className="text-xs font-black uppercase tracking-widest">Configuration</span>
          </button>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-5 py-3 ${currentTheme.radius} text-red-500 hover:bg-red-50 transition-all font-bold">
            <LogOut size={20} /> <span className="text-xs font-black uppercase tracking-widest">Quitter</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-x-hidden relative">
        {/* Profile Header */}
        <header className="relative w-full h-56 overflow-hidden group">
           <div className={`absolute inset-0 bg-gradient-to-r ${currentUser.bannerColor} transition-all duration-1000`}>
             <div className="absolute inset-0 bg-black/30 backdrop-blur-[1px]" />
           </div>
           <div className="max-w-7xl mx-auto px-6 md:px-12 flex items-end h-full pb-10 gap-8 relative z-10">
              <div className="relative">
                 <div className={`w-36 h-36 rounded-full border-[8px] border-white dark:border-slate-900 overflow-hidden shadow-[0_20px_50px_rgba(0,0,0,0.3)] bg-slate-200 transition-all ${currentUser.decoration || ''}`}>
                    <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" />
                 </div>
                 <div className={`absolute -bottom-2 -right-2 ${currentTheme.primary} text-white w-12 h-12 rounded-full border-[6px] border-white dark:border-slate-900 flex items-center justify-center font-black text-sm shadow-xl`}>
                    {currentUser.level}
                 </div>
              </div>
              <div className="mb-2 flex-1">
                 <h1 className="text-5xl font-black text-white drop-shadow-[0_2px_10px_rgba(0,0,0,0.5)] tracking-tighter mb-4">{currentUser.name}</h1>
                 <div className="flex items-center gap-6">
                    <div className="flex-1 max-w-md h-3.5 bg-black/40 rounded-full overflow-hidden backdrop-blur-md border border-white/10">
                       <div className="h-full bg-gradient-to-r from-white to-white/60 shadow-[0_0_20px_white] transition-all duration-1000" style={{ width: `${(currentUser.xp % 1000) / 10}%` }} />
                    </div>
                    <span className="text-xs font-black uppercase text-white tracking-[0.2em] drop-shadow-md">{currentUser.xp % 1000} / 1000 XP</span>
                 </div>
              </div>
              <button 
                onClick={() => setIsTaskModalOpen(true)}
                className={`hidden lg:flex items-center gap-3 bg-white text-slate-900 px-8 py-4 ${currentTheme.radius} font-black text-xs uppercase tracking-widest transition-all active:scale-90 shadow-2xl hover:bg-slate-50`}
              >
                <Plus size={22} strokeWidth={4} /> Nouvelle Quête
              </button>
           </div>
        </header>

        <div className={`p-6 md:p-12 max-w-7xl mx-auto w-full ${currentTheme.animation}`}>
           {renderContent()}
        </div>

        {/* Floating Add Button for Mobile */}
        <button 
          onClick={() => setIsTaskModalOpen(true)}
          className={`lg:hidden fixed bottom-8 right-8 w-20 h-20 rounded-full ${currentTheme.primary} text-white shadow-[0_15px_40px_rgba(0,0,0,0.4)] flex items-center justify-center z-50 active:scale-90 transition-transform ${currentTheme.glow}`}
        >
          <Plus size={40} strokeWidth={4} />
        </button>
      </main>

      {isTaskModalOpen && (
        <TaskModal 
          theme={theme}
          task={editingTask}
          onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }}
          onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask}
        />
      )}
    </div>
  );
};

