import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, CheckSquare, Grid2X2, Timer, BarChart3, 
  CalendarDays, Plus, LogOut, Sparkles, Settings, Palette 
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, TaskDifficulty } from './types';
import { THEMES } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning' | 'settings';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<View>('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      handleLogin(JSON.parse(savedUser));
    } else {
      setIsAuthLoading(false);
    }
  }, []);

  useEffect(() => {
    if (currentUser) {
      // Sync with LocalStorage on every relevant state change
      const userData: UserData = { tasks, unavailabilities, theme };
      mockAuthService.saveUserData(currentUser.id, userData);
      localStorage.setItem('evo_current_user', JSON.stringify(currentUser));

      const currentThemeData = THEMES[theme];
      document.body.style.backgroundColor = currentThemeData.id === 'dark' ? '#000' : '#f8fafc';
      document.documentElement.style.setProperty('--app-font', currentThemeData.font);

      if (theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [tasks, theme, unavailabilities, currentUser]);

  const handleLogin = async (user: User) => {
    const userData = await mockAuthService.getUserData(user.id);
    setCurrentUser(user);
    setTasks(userData.tasks);
    setUnavailabilities(userData.unavailabilities);
    setTheme(userData.theme);
    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('evo_current_user');
    setActiveTab('dashboard');
  };

  const gainXP = (amount: number) => {
    if (!currentUser) return;
    const newXP = currentUser.xp + amount;
    const newLevel = Math.floor(newXP / 1000) + 1;
    setCurrentUser({ ...currentUser, xp: newXP, level: newLevel });
  };

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone) gainXP(t.difficulty === TaskDifficulty.HARD ? 200 : t.difficulty === TaskDifficulty.MEDIUM ? 150 : 100);
        return { ...t, ...updates, completedAt: isNowDone ? Date.now() : t.completedAt };
      }
      return t;
    }));
  };

  const renderContent = () => {
    if (!currentUser) return null;
    switch (activeTab) {
      case 'dashboard': return <Dashboard tasks={tasks} theme={theme} unavailabilities={unavailabilities} onAddTask={() => setIsTaskModalOpen(true)} onUpdateTask={updateTask} onAddUnavailability={() => {}} onDeleteUnavailability={() => {}} />;
      case 'tasks': return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => {setEditingTask(t); setIsTaskModalOpen(true);}} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix': return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'focus': return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} onXpGain={gainXP} user={currentUser} />;
      case 'stats': return <ProgressTracking tasks={tasks} theme={theme} />;
      case 'planning': return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'settings': return <ProfileSettings user={currentUser} onUpdateUser={setCurrentUser} theme={theme} onThemeChange={setTheme} />;
      default: return null;
    }
  };

  const currentTheme = THEMES[theme];

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'tasks', label: 'Mes Quêtes', icon: CheckSquare },
    { id: 'matrix', label: 'Eisenhower', icon: Grid2X2 },
    { id: 'focus', label: 'Mode Focus', icon: Timer },
    { id: 'stats', label: 'Progression', icon: BarChart3 },
    { id: 'planning', label: 'Planning IA', icon: CalendarDays },
  ];

  if (isAuthLoading) return null;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  return (
    <div className={`min-h-screen flex flex-col md:flex-row transition-colors duration-500 overflow-hidden ${currentTheme.bg} ${currentTheme.text}`}>
      {/* Sidebar */}
      <aside className={`w-full md:w-72 flex flex-col ${currentTheme.card} border-r ${currentTheme.border} h-screen sticky top-0 z-50 shadow-2xl`}>
        <div className="p-8 flex items-center gap-4">
          <div className={`w-12 h-12 rounded-2xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg`}>
            <Sparkles size={28} />
          </div>
          <span className="text-3xl font-black tracking-tighter">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as View)}
              className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl transition-all ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-xl` 
                : 'text-slate-500 hover:bg-black/5 dark:hover:bg-white/5 font-bold'
              }`}
            >
              <item.icon size={20} />
              <span className="text-sm uppercase tracking-widest">{item.label}</span>
            </button>
          ))}

          <div className="pt-8 pb-4 px-6 border-t ${currentTheme.border} mt-6">
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2"><Palette size={14} /> Thèmes</span>
            <div className="mt-4 grid grid-cols-5 gap-2">
              {(Object.keys(THEMES) as ThemeType[]).map((t) => (
                <button 
                  key={t}
                  onClick={() => setTheme(t)}
                  className={`h-8 rounded-lg border-2 transition-all ${theme === t ? 'border-white ring-2 ring-indigo-500 scale-110' : 'border-transparent opacity-50 hover:opacity-100'}`}
                  style={{ backgroundColor: THEMES[t].id === 'dark' ? '#1e293b' : THEMES[t].primary.replace('bg-', '') }}
                />
              ))}
            </div>
          </div>
        </nav>

        <div className="p-6 border-t ${currentTheme.border} space-y-2">
          <button onClick={() => setActiveTab('settings')} className="w-full flex items-center gap-3 px-6 py-3 rounded-xl text-slate-500 hover:bg-black/5 transition-all">
            <Settings size={18} /> <span className="text-xs font-black uppercase tracking-widest">Configuration</span>
          </button>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-6 py-3 rounded-xl text-red-500 hover:bg-red-50 transition-all">
            <LogOut size={18} /> <span className="text-xs font-black uppercase tracking-widest">Quitter</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto">
        <header className="relative w-full h-56 overflow-hidden">
           <div className={`absolute inset-0 bg-gradient-to-r ${currentUser.bannerColor} transition-all duration-1000 opacity-90`}>
             <div className="absolute inset-0 bg-black/20 backdrop-blur-[1px]" />
           </div>
           <div className="max-w-6xl mx-auto px-8 flex items-end h-full pb-8 gap-8 relative z-10">
              <div className="relative">
                 <div className={`w-36 h-36 rounded-full border-[8px] border-white dark:border-slate-900 overflow-hidden shadow-2xl ${currentUser.decoration || ''}`}>
                    <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" />
                 </div>
                 <div className={`absolute -bottom-2 -right-2 ${currentTheme.primary} text-white w-12 h-12 rounded-full border-4 border-white dark:border-slate-900 flex items-center justify-center font-black text-sm`}>
                    {currentUser.level}
                 </div>
              </div>
              <div className="flex-1 pb-2">
                 <h1 className="text-4xl font-black text-white drop-shadow-md tracking-tighter mb-4">{currentUser.name}</h1>
                 <div className="flex items-center gap-4">
                    <div className="flex-1 max-w-sm h-3 bg-black/40 rounded-full overflow-hidden border border-white/10">
                       <div className="h-full bg-white shadow-[0_0_15px_white] transition-all duration-1000" style={{ width: `${(currentUser.xp % 1000) / 10}%` }} />
                    </div>
                    <span className="text-[10px] font-black uppercase text-white tracking-widest">{currentUser.xp % 1000} / 1000 XP</span>
                 </div>
              </div>
              <button onClick={() => setIsTaskModalOpen(true)} className="hidden lg:flex items-center gap-2 bg-white text-slate-900 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-2xl">
                <Plus size={20} strokeWidth={3} /> Nouvelle Quête
              </button>
           </div>
        </header>

        <div className="p-8 md:p-12 max-w-6xl mx-auto">
           {renderContent()}
        </div>
      </main>

      {isTaskModalOpen && (
        <TaskModal theme={theme} task={editingTask} onClose={() => {setIsTaskModalOpen(false); setEditingTask(undefined);}} onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Task, TaskStatus, ThemeType, User } from '../../types';
import { THEMES } from '../../constants';
import { Play, Pause, RotateCcw, Coffee, Brain, Zap } from 'lucide-react';

interface PomodoroProps {
  theme: ThemeType;
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  onXpGain: (amount: number) => void;
  user: User;
}

const Pomodoro: React.FC<PomodoroProps> = ({ theme, tasks, onUpdateTask, onXpGain, user }) => {
  const currentTheme = THEMES[theme];
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isActive, timeLeft]);

  const handleTimerComplete = () => {
    setIsActive(false);
    if (mode === 'work') {
      if (selectedTask) {
        const task = tasks.find(t => t.id === selectedTask);
        if (task) onUpdateTask(selectedTask, { actualMinutes: (task.actualMinutes || 0) + 25 });
      }
      onXpGain(200); 
      setMode('break');
      setTimeLeft(5 * 60);
      setIsActive(true); // Lance le repos automatiquement
    } else {
      setMode('work');
      setTimeLeft(25 * 60);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progress = (mode === 'work' ? 25 * 60 - timeLeft : 5 * 60 - timeLeft) / (mode === 'work' ? 25 * 60 : 5 * 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center space-y-12 py-8">
      {/* Switcher */}
      <div className={`flex gap-2 p-2 bg-slate-200/50 dark:bg-slate-800 rounded-3xl backdrop-blur-md`}>
        <button 
          onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
          className={`px-8 py-3 rounded-2xl text-xs font-black transition-all ${mode === 'work' ? `${currentTheme.primary} text-white shadow-xl` : 'text-slate-500 hover:bg-black/5'}`}
        >
          SESSION TRAVAIL
        </button>
        <button 
          onClick={() => { setMode('break'); setTimeLeft(5 * 60); setIsActive(false); }}
          className={`px-8 py-3 rounded-2xl text-xs font-black transition-all ${mode === 'break' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:bg-black/5'}`}
        >
          MODE REPOS
        </button>
      </div>

      {mode === 'work' ? (
        <div className="flex flex-col items-center space-y-12 w-full max-w-lg">
          <div className="relative group">
            {/* Glow effect for dark theme visibility */}
            <div className={`absolute inset-0 rounded-full blur-[60px] opacity-20 ${currentTheme.primary}`} />

            <div className={`w-80 h-80 rounded-full border-[12px] border-slate-200 dark:border-slate-800 flex items-center justify-center relative bg-white dark:bg-slate-900 shadow-2xl`}>
                <div className={`absolute bottom-0 w-full ${currentTheme.primary} opacity-10 transition-all duration-1000 ease-linear`} style={{ height: `${progress}%` }} />
                <div className={`text-8xl font-black tabular-nums z-10 ${currentTheme.timerColor} tracking-tighter`}>
                  {formatTime(timeLeft)}
                </div>
            </div>
          </div>

          <div className="flex gap-8 items-center">
            <button onClick={() => {setIsActive(false); setTimeLeft(25*60);}} className="p-4 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-400 hover:text-slate-600 transition-all"><RotateCcw size={28} /></button>
            <button onClick={() => setIsActive(!isActive)} className={`p-10 rounded-full ${currentTheme.primary} text-white shadow-2xl hover:scale-105 transition-all`}>
              {isActive ? <Pause size={48} fill="currentColor" /> : <Play size={48} fill="currentColor" className="ml-1" />}
            </button>
          </div>

          <div className="w-full">
            <p className="text-center text-[10px] font-black uppercase text-slate-400 tracking-widest mb-4">Quête associée</p>
            <select className={`w-full ${currentTheme.input} rounded-2xl px-6 py-4 font-bold outline-none shadow-sm`} value={selectedTask || ''} onChange={(e) => setSelectedTask(e.target.value)}>
              <option value="">Cliquer pour sélectionner une quête</option>
              {tasks.filter(t => t.status !== TaskStatus.DONE).map(t => <option key={t.id} value={t.id}>{t.title}</option>)}
            </select>
          </div>
        </div>
      ) : (
        <div className={`w-full max-w-2xl ${currentTheme.card} ${currentTheme.radius} border ${currentTheme.border} p-12 text-center shadow-2xl`}>
          <div className="mb-10">
            <h2 className="text-6xl font-black mb-2 tracking-tighter text-slate-900 dark:text-white">{formatTime(timeLeft)}</h2>
            <p className="text-xs font-black uppercase tracking-widest text-slate-400">Temps de repos restant</p>
          </div>

          <MiniGame onScore={() => onXpGain(10)} />

          <div className="mt-12 flex items-center justify-center gap-4 text-emerald-500 font-black uppercase text-sm animate-pulse">
            <Zap size={20} fill="currentColor" /> Clique sur la cible pour gagner de l'XP !
          </div>
        </div>
      )}
    </div>
  );
};

const MiniGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const move = () => {
    setPos({ x: Math.random() * 70 + 15, y: Math.random() * 70 + 15 });
    onScore();
  };
  return (
    <div className="relative w-full h-80 bg-slate-50 dark:bg-black/40 rounded-[2.5rem] border-2 border-dashed border-slate-200 dark:border-white/5 overflow-hidden shadow-inner cursor-crosshair">
      <button 
        onClick={move} 
        className="absolute w-20 h-20 bg-indigo-600 rounded-full shadow-[0_0_30px_rgba(79,70,229,0.5)] flex items-center justify-center text-white transition-all active:scale-75 hover:scale-110" 
        style={{ left: `${pos.x}%`, top: `${pos.y}%`, transform: 'translate(-50%, -50%)' }}
      >
        <Zap size={40} fill="white" />
      </button>
    </div>
  );
};

