import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'focus' | 'stats' | 'planning' | 'settings';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<View>('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      handleLogin(JSON.parse(savedUser));
    } else {
      setIsAuthLoading(false);
    }
  }, []);

  // Persistance Automatique de TOUTE l'application
  useEffect(() => {
    if (currentUser) {
      const userData: UserData = { tasks, unavailabilities, theme };
      mockAuthService.saveUserData(currentUser.id, userData);
      localStorage.setItem('evo_current_user', JSON.stringify(currentUser));

      // Update global users list for persistent login/pwd
      const users: any[] = JSON.parse(localStorage.getItem('evo_sql_users') || '[]');
      const updatedUsers = users.map(u => u.id === currentUser.id ? { ...u, ...currentUser } : u);
      localStorage.setItem('evo_sql_users', JSON.stringify(updatedUsers));

      const currentThemeData = THEMES[theme];
      document.body.style.backgroundColor = currentThemeData.id === 'dark' ? '#000' : '#f8fafc';
      document.documentElement.style.setProperty('--app-font', currentThemeData.font);

      if (theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [tasks, theme, unavailabilities, currentUser]);

  const handleLogin = async (user: User) => {
    const userData = await mockAuthService.getUserData(user.id);
    setCurrentUser(user);
    setTasks(userData.tasks);
    setUnavailabilities(userData.unavailabilities);
    setTheme(userData.theme);
    setIsAuthLoading(false);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('evo_current_user');
    setActiveTab('dashboard');
  };

  const gainXP = (amount: number) => {
    if (!currentUser) return;
    const newXP = currentUser.xp + amount;
    const newLevel = Math.floor(newXP / 1000) + 1;
    setCurrentUser({ ...currentUser, xp: newXP, level: newLevel });
  };

  const addTask = (taskData: any) => {
    const newTask: Task = {
      ...taskData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now(),
      actualMinutes: 0
    };
    setTasks([...tasks, newTask]);
    setIsTaskModalOpen(false);
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone) gainXP(t.difficulty === TaskDifficulty.HARD ? 200 : t.difficulty === TaskDifficulty.MEDIUM ? 150 : 100);
        return { ...t, ...updates, completedAt: isNowDone ? Date.now() : t.completedAt };
      }
      return t;
    }));
  };

  const renderContent = () => {
    if (!currentUser) return null;
    switch (activeTab) {
      case 'dashboard': 
        return <Dashboard 
          tasks={tasks} 
          theme={theme} 
          unavailabilities={unavailabilities} 
          onAddTask={() => setIsTaskModalOpen(true)} 
          onUpdateTask={updateTask} 
          onAddUnavailability={() => {}} 
          onDeleteUnavailability={() => {}} 
          onStartFocus={() => setActiveTab('focus')} // Connecté au Dashboard
        />;
      case 'tasks': return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => {setEditingTask(t); setIsTaskModalOpen(true);}} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix': return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'focus': return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} onXpGain={gainXP} user={currentUser} />;
      case 'stats': return <ProgressTracking tasks={tasks} theme={theme} />;
      case 'planning': return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'settings': return <ProfileSettings user={currentUser} onUpdateUser={setCurrentUser} theme={theme} onThemeChange={setTheme} />;
      default: return null;
    }
  };

  const currentTheme = THEMES[theme];

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'tasks', label: 'Mes Quêtes', icon: CheckSquare },
    { id: 'matrix', label: 'Eisenhower', icon: Grid2X2 },
    { id: 'focus', label: 'Mode Focus', icon: Timer },
    { id: 'stats', label: 'Progression', icon: BarChart3 },
    { id: 'planning', label: 'Planning IA', icon: CalendarDays },
  ];

  if (isAuthLoading) return null;
  if (!currentUser) return <AuthScreen onLogin={handleLogin} />;

  return (
    <div className={`min-h-screen flex flex-col md:flex-row transition-colors duration-500 overflow-hidden ${currentTheme.bg} ${currentTheme.text}`}>
      <aside className={`w-full md:w-72 flex flex-col ${currentTheme.card} border-r ${currentTheme.border} h-screen sticky top-0 z-50 shadow-2xl`}>
        <div className="p-8 flex items-center gap-4">
          <div className={`w-12 h-12 rounded-2xl ${currentTheme.primary} flex items-center justify-center text-white shadow-lg`}>
            <Sparkles size={28} />
          </div>
          <span className="text-3xl font-black tracking-tighter">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-1 overflow-y-auto">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as View)}
              className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl transition-all ${
                activeTab === item.id 
                ? `${currentTheme.primary} text-white shadow-xl` 
                : 'text-slate-500 hover:bg-black/5 dark:hover:bg-white/5 font-bold'
              }`}
            >
              <item.icon size={20} />
              <span className="text-sm uppercase tracking-widest">{item.label}</span>
            </button>
          ))}

          <div className="pt-8 pb-4 px-6 border-t ${currentTheme.border} mt-6">
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2"><Palette size={14} /> Thèmes</span>
            <div className="mt-4 grid grid-cols-5 gap-2">
              {(Object.keys(THEMES) as ThemeType[]).map((t) => (
                <button 
                  key={t}
                  onClick={() => setTheme(t)}
                  className={`h-8 rounded-lg border-2 transition-all ${theme === t ? 'border-white ring-2 ring-indigo-500 scale-110' : 'border-transparent opacity-50 hover:opacity-100'}`}
                  style={{ backgroundColor: THEMES[t].id === 'dark' ? '#1e293b' : THEMES[t].primary.replace('bg-', '') }}
                />
              ))}
            </div>
          </div>
        </nav>

        <div className="p-6 border-t ${currentTheme.border} space-y-2">
          <button onClick={() => setActiveTab('settings')} className="w-full flex items-center gap-3 px-6 py-3 rounded-xl text-slate-500 hover:bg-black/5 transition-all">
            <Settings size={18} /> <span className="text-xs font-black uppercase tracking-widest text-left">Profil</span>
          </button>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-6 py-3 rounded-xl text-red-500 hover:bg-red-50 transition-all">
            <LogOut size={18} /> <span className="text-xs font-black uppercase tracking-widest text-left">Quitter</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto">
        <header className="relative w-full h-64 overflow-hidden shadow-2xl">
           <div className={`absolute inset-0 bg-slate-900 transition-all duration-1000`}>
              <img 
                src={currentUser.bannerUrl || "https://images.unsplash.com/photo-1614850523296-d8c1af93d400?q=80&w=2070&auto=format&fit=crop"} 
                alt="Banner" 
                className="w-full h-full object-cover opacity-60"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent" />
           </div>
           <div className="max-w-6xl mx-auto px-8 flex items-end h-full pb-8 gap-8 relative z-10">
              <div className="relative">
                 {/* Preview des cosmétiques (Auras, Cadres) */}
                 <div className={`w-40 h-40 rounded-full border-[8px] border-white dark:border-slate-900 overflow-hidden shadow-2xl relative z-10 ${currentUser.decoration || ''}`}>
                    <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" />
                 </div>
                 <div className={`absolute -bottom-2 -right-2 ${currentTheme.primary} text-white w-14 h-14 rounded-full border-4 border-white dark:border-slate-900 flex items-center justify-center font-black text-lg z-20`}>
                    {currentUser.level}
                 </div>
              </div>
              <div className="flex-1 pb-4">
                 <h1 className="text-5xl font-black text-white drop-shadow-2xl tracking-tighter mb-4">{currentUser.name}</h1>
                 <div className="flex items-center gap-6">
                    <div className="flex-1 max-w-sm h-4 bg-black/40 rounded-full overflow-hidden border border-white/10 backdrop-blur-md">
                       <div className="h-full bg-white shadow-[0_0_20px_white] transition-all duration-1000" style={{ width: `${(currentUser.xp % 1000) / 10}%` }} />
                    </div>
                    <span className="text-xs font-black uppercase text-white tracking-widest drop-shadow-lg">{currentUser.xp % 1000} / 1000 XP</span>
                 </div>
              </div>
              <button onClick={() => setIsTaskModalOpen(true)} className="hidden lg:flex items-center gap-2 bg-white text-slate-900 px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-2xl mb-4">
                <Plus size={24} strokeWidth={4} /> Nouvelle Quête
              </button>
           </div>
        </header>

        <div className="p-8 md:p-12 max-w-6xl mx-auto">
           {renderContent()}
        </div>
      </main>

      {isTaskModalOpen && (
        <TaskModal theme={theme} task={editingTask} onClose={() => {setIsTaskModalOpen(false); setEditingTask(undefined);}} onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : addTask} />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { Task, TaskStatus, ThemeType, EisenhowerQuadrant } from '../types';
import { THEMES } from '../constants';
import { CheckCircle2, Clock, Sparkles, Zap, AlertCircle, Plus } from 'lucide-react';

interface DashboardProps {
  tasks: Task[];
  theme: ThemeType;
  unavailabilities: any[];
  onAddTask: () => void;
  onUpdateTask: (id: string, updates: any) => void;
  onAddUnavailability: (unavail: any) => void;
  onDeleteUnavailability: (id: string) => void;
  onStartFocus: () => void; // Ajout du lien vers le Timer
}

const Dashboard: React.FC<DashboardProps> = ({ 
  tasks, 
  theme, 
  onUpdateTask,
  onAddTask,
  onStartFocus
}) => {
  const currentTheme = THEMES[theme];
  const pendingTasks = tasks.filter(t => t.status !== TaskStatus.DONE);
  const completedToday = tasks.filter(t => t.status === TaskStatus.DONE && t.completedAt && new Date(t.completedAt).toDateString() === new Date().toDateString()).length;
  const totalFocusMinutes = tasks.reduce((acc, t) => acc + (t.actualMinutes || 0), 0);

  return (
    <div className="space-y-12 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard label="Journal de Quêtes" value={pendingTasks.length.toString()} icon={Zap} color="text-indigo-500" theme={theme} />
        <StatCard label="Succès du Jour" value={completedToday.toString()} icon={CheckCircle2} color="text-emerald-500" theme={theme} />
        <StatCard label="Total Focus" value={`${Math.floor(totalFocusMinutes / 60)}h ${totalFocusMinutes % 60}m`} icon={Clock} color="text-blue-500" theme={theme} />
        <StatCard label="Prestige XP" value={`${tasks.filter(t => t.status === TaskStatus.DONE).reduce((acc, t) => acc + (t.difficulty === 'hard' ? 200 : t.difficulty === 'medium' ? 150 : 100), 0)}`} icon={Sparkles} color="text-amber-500" theme={theme} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-8">
          <div className={`${currentTheme.card} ${currentTheme.radius} border ${currentTheme.border} p-10 ${currentTheme.shadow} transition-all duration-500`}>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-3xl font-black flex items-center gap-4">
                 <AlertCircle size={28} className={currentTheme.secondary} /> Objectifs Prioritaires
              </h3>
              <button onClick={onAddTask} className={`p-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-slate-500 hover:text-indigo-500 transition-all ${currentTheme.shadow}`}>
                <Plus size={24} />
              </button>
            </div>

            <div className="space-y-4">
              {pendingTasks.length > 0 ? (
                pendingTasks.slice(0, 5).map(task => (
                  <div key={task.id} className={`p-6 bg-slate-50 dark:bg-slate-800/60 ${currentTheme.radius} border border-black/5 flex items-center justify-between group hover:scale-[1.01] transition-all`}>
                    <div className="flex items-center gap-6">
                      <div className={`w-4 h-4 rounded-full shadow-[0_0_15px_rgba(0,0,0,0.2)] ${task.quadrant === EisenhowerQuadrant.DO_FIRST ? 'bg-red-500' : 'bg-emerald-500'}`} />
                      <div>
                        <p className="font-bold text-lg leading-tight mb-2">{task.title}</p>
                        <div className="flex items-center gap-4">
                           <span className="text-xs text-slate-400 uppercase font-black tracking-widest">{task.estimatedMinutes} min estimé</span>
                           <span className={`text-[10px] font-black uppercase px-3 py-1 rounded-lg ${task.difficulty === 'hard' ? 'bg-rose-500/10 text-rose-500' : task.difficulty === 'medium' ? 'bg-amber-500/10 text-amber-500' : 'bg-emerald-500/10 text-emerald-500'}`}>{task.difficulty}</span>
                        </div>
                      </div>
                    </div>
                    <button onClick={() => onUpdateTask(task.id, { status: TaskStatus.DONE })} className={`p-4 bg-white dark:bg-slate-900 text-slate-200 hover:text-emerald-500 rounded-2xl shadow-md border border-black/5 transition-all active:scale-90`}>
                      <CheckCircle2 size={28} />
                    </button>
                  </div>
                ))
              ) : (
                <div className="text-center py-24 opacity-30 italic">
                   <p className="font-black text-xl text-slate-500 uppercase tracking-widest">Toutes les quêtes sont terminées ! ✨</p>
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="space-y-8">
           <div className={`${currentTheme.card} ${currentTheme.radius} border ${currentTheme.border} p-10 text-center ${currentTheme.shadow} transition-all duration-500`}>
              <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 mb-10">SESSION RAPIDE</h4>
              <div className="text-7xl font-black tracking-tighter tabular-nums mb-6 text-slate-900 dark:text-white drop-shadow-xl">25:00</div>
              <p className="text-sm font-bold text-slate-500 mb-10 italic leading-relaxed">Boost ton XP en complétant une session maintenant !</p>
              <button 
                onClick={onStartFocus} // Action réelle connectée
                className={`${currentTheme.button} w-full py-6 ${currentTheme.radius} font-black text-xs uppercase tracking-[0.25em] shadow-xl active:scale-95 transition-all`}
              >
                LANCER FOCUS
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ label, value, icon: Icon, color, theme }: any) => {
  const currentTheme = THEMES[theme as ThemeType];
  return (
    <div className={`${currentTheme.card} ${currentTheme.radius} p-8 border ${currentTheme.border} ${currentTheme.shadow} flex items-center gap-6 group hover:scale-[1.03] transition-all duration-300`}>
      <div className={`p-5 rounded-[1.2rem] bg-slate-100 dark:bg-slate-800 ${color} shadow-inner group-hover:rotate-12 transition-transform`}><Icon size={32} strokeWidth={3} /></div>
      <div>
        <p className="text-[10px] font-black opacity-40 uppercase tracking-[0.2em] mb-2">{label}</p>
        <p className="text-3xl font-black tracking-tight tabular-nums text-slate-900 dark:text-white">{value}</p>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { User, ThemeType } from '../../types';
import { THEMES, LEVEL_REQUIREMENTS } from '../../constants';
import { Save, Camera, Sparkles, Trophy, Lock, Palette, ImageIcon } from 'lucide-react';

interface ProfileSettingsProps {
  user: User;
  onUpdateUser: (updates: User) => void;
  theme: ThemeType;
  onThemeChange: (theme: ThemeType) => void;
}

const ProfileSettings: React.FC<ProfileSettingsProps> = ({ user, onUpdateUser, theme, onThemeChange }) => {
  const currentTheme = THEMES[theme];
  const [name, setName] = useState(user.name);
  const [avatar, setAvatar] = useState(user.avatar);
  const [bannerUrl, setBannerUrl] = useState(user.bannerUrl);

  const handleSave = () => {
    onUpdateUser({ ...user, name, avatar, bannerUrl });
    alert("Profil sauvegardé avec succès ! ✨");
  };

  const decorations = [
    { id: 'neon', level: 5, label: 'Aura Focus', class: 'shadow-[0_0_35px_rgba(99,102,241,1)] ring-4 ring-indigo-500/50' },
    { id: 'gold', level: 8, label: 'Cadre Majestueux', class: 'border-[8px] border-amber-400 shadow-[0_0_20px_rgba(251,191,36,0.5)]' },
    { id: 'fire', level: 12, label: 'Cercle de Feu', class: 'ring-[10px] ring-rose-500 animate-pulse shadow-[0_0_40px_rgba(244,63,94,0.6)]' }
  ];

  return (
    <div className="max-w-4xl mx-auto space-y-8 pb-10 animate-in fade-in duration-500">
      {/* Themes Selection */}
      <div className={`${currentTheme.card} rounded-[2rem] border ${currentTheme.border} p-8 shadow-sm`}>
        <h3 className="text-lg font-black mb-6 flex items-center gap-3 text-slate-900 dark:text-white"><Palette size={20} className={currentTheme.secondary} /> Style de l'Application</h3>
        <div className="grid grid-cols-5 gap-4">
           {(Object.keys(THEMES) as ThemeType[]).map((t) => (
             <button 
               key={t}
               onClick={() => onThemeChange(t)}
               className={`h-16 rounded-2xl border-2 transition-all flex items-center justify-center ${theme === t ? 'border-indigo-600 scale-105 shadow-md' : 'border-transparent opacity-60 hover:opacity-100'}`}
               style={{ backgroundColor: THEMES[t].primary.replace('bg-', '') }}
             >
                <div className={`w-6 h-6 rounded-full bg-white shadow-inner ${theme === t ? 'scale-100' : 'scale-0'} transition-transform`} />
             </button>
           ))}
        </div>
      </div>

      {/* Profile Identity */}
      <div className={`${currentTheme.card} rounded-[3rem] border ${currentTheme.border} p-10 shadow-sm`}>
        <h3 className="text-lg font-black mb-10 flex items-center gap-3 text-slate-900 dark:text-white"><Sparkles size={20} className="text-indigo-500" /> Mon Identité RPG</h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
          <div className="space-y-8">
            <div className="space-y-3">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Nom de joueur</label>
              <input type="text" value={name} onChange={(e) => setName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl px-6 py-5 font-bold text-sm outline-none focus:ring-4 ring-indigo-500/20 shadow-inner" />
            </div>
            <div className="space-y-3">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Lien Avatar (Image/GIF)</label>
              <div className="relative">
                <input type="text" value={avatar} onChange={(e) => setAvatar(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl pl-12 pr-4 py-5 font-bold text-sm outline-none focus:ring-4 ring-indigo-500/20 shadow-inner" />
                <Camera className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={22} />
              </div>
            </div>
          </div>

          <div className="space-y-8">
            <div className="space-y-3">
              <div className="flex justify-between">
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Lien Bannière (Unlock Lvl {LEVEL_REQUIREMENTS.BANNER})</label>
                {user.level < LEVEL_REQUIREMENTS.BANNER && <Lock size={14} className="text-slate-300" />}
              </div>
              <div className="relative">
                <input 
                  type="text" 
                  disabled={user.level < LEVEL_REQUIREMENTS.BANNER}
                  value={bannerUrl} 
                  onChange={(e) => setBannerUrl(e.target.value)} 
                  placeholder="URL d'une image ou d'un GIF..."
                  className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-2xl pl-12 pr-4 py-5 font-bold text-sm outline-none focus:ring-4 ring-indigo-500/20 shadow-inner disabled:opacity-30" 
                />
                <ImageIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={22} />
              </div>
            </div>
          </div>
        </div>

        <div className="mt-12 space-y-6">
           <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Auras & Cadres (Unlock Lvl {LEVEL_REQUIREMENTS.DECORATION}+)</label>
           <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
              {decorations.map((d) => (
                <button 
                  key={d.id}
                  disabled={user.level < d.level}
                  onClick={() => onUpdateUser({ ...user, decoration: d.class })}
                  className={`p-6 rounded-3xl border transition-all flex items-center justify-between ${user.decoration === d.class ? 'bg-indigo-600 text-white border-transparent shadow-xl ring-4 ring-indigo-300' : 'bg-slate-50 dark:bg-slate-800 border-black/5 hover:border-indigo-500/30'}`}
                >
                  <div className="text-left">
                    <p className="text-xs font-black uppercase tracking-tight">{d.label}</p>
                    <p className="text-[10px] opacity-60">Req. Lvl {d.level}</p>
                  </div>
                  {user.level < d.level ? <Lock size={16} className="text-slate-400" /> : <Trophy size={16} className={user.decoration === d.class ? 'text-white' : 'text-amber-500'} />}
                </button>
              ))}
           </div>
        </div>

        <button onClick={handleSave} className={`${currentTheme.button} mt-12 w-full py-6 rounded-3xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all`}>
          <Save size={22} strokeWidth={3} /> Enregistrer mon Profil
        </button>
      </div>
    </div>
  );
};

export default ProfileSettings;

import { User, UserData, TaskStatus, TaskPriority, EisenhowerQuadrant, ThemeType } from '../types';

const USERS_DB_KEY = 'evo_sql_users';
const DATA_DB_PREFIX = 'evo_sql_data_';

const delay = (ms: number) => new Promise(res => setTimeout(res, ms));

export const mockAuthService = {
  async signup(email: string, name: string, password: string): Promise<User> {
    await delay(800);
    const users: any[] = JSON.parse(localStorage.getItem(USERS_DB_KEY) || '[]');

    if (users.find(u => u.email === email)) {
      throw new Error("Cet email est déjà utilisé.");
    }

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      email,
      name,
      avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${email}`,
      level: 1,
      xp: 0,
      bannerUrl: 'https://images.unsplash.com/photo-1614850523296-d8c1af93d400?q=80&w=2070&auto=format&fit=crop',
      decoration: null,
      unlockedItems: []
    };

    users.push({ ...newUser, password }); 
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

    const defaultData: UserData = {
      tasks: [],
      unavailabilities: [],
      theme: 'lime'
    };
    localStorage.setItem(`${DATA_DB_PREFIX}${newUser.id}`, JSON.stringify(defaultData));

    return newUser;
  },

  async login(email: string, password: string): Promise<User> {
    await delay(600);
    const users: any[] = JSON.parse(localStorage.getItem(USERS_DB_KEY) || '[]');
    const user = users.find(u => u.email === email && u.password === password);

    if (!user) {
      throw new Error("Email ou mot de passe incorrect.");
    }

    const { password: _, ...userWithoutPassword } = user;
    return userWithoutPassword as User;
  },

  async getUserData(userId: string): Promise<UserData> {
    const data = localStorage.getItem(`${DATA_DB_PREFIX}${userId}`);
    return data ? JSON.parse(data) : { tasks: [], unavailabilities: [], theme: 'lime' };
  },

  async saveUserData(userId: string, data: UserData): Promise<void> {
    localStorage.setItem(`${DATA_DB_PREFIX}${userId}`, JSON.stringify(data));
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Task, TaskStatus, ThemeType, User } from '../../types';
import { THEMES } from '../../constants';
import { Play, Pause, RotateCcw, Coffee, Brain, Zap } from 'lucide-react';

interface PomodoroProps {
  theme: ThemeType;
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  onXpGain: (amount: number) => void;
  user: User;
}

const Pomodoro: React.FC<PomodoroProps> = ({ theme, tasks, onUpdateTask, onXpGain, user }) => {
  const currentTheme = THEMES[theme];
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isActive, timeLeft]);

  const handleTimerComplete = () => {
    setIsActive(false);
    if (mode === 'work') {
      if (selectedTask) {
        const task = tasks.find(t => t.id === selectedTask);
        if (task) onUpdateTask(selectedTask, { actualMinutes: (task.actualMinutes || 0) + 25 });
      }
      onXpGain(250); // Plus d'XP pour une session complète
      setMode('break');
      setTimeLeft(5 * 60); // 5 minutes de repos
      setIsActive(true); // Lance le repos automatiquement pour le mini-jeu
    } else {
      setMode('work');
      setTimeLeft(25 * 60);
      setIsActive(false);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progress = (mode === 'work' ? 25 * 60 - timeLeft : 5 * 60 - timeLeft) / (mode === 'work' ? 25 * 60 : 5 * 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center space-y-12 py-8 animate-in fade-in duration-500">
      <div className={`flex gap-3 p-2 bg-slate-200/50 dark:bg-slate-800 rounded-3xl backdrop-blur-md border ${currentTheme.border}`}>
        <button 
          onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
          className={`px-8 py-4 rounded-2xl text-xs font-black tracking-widest transition-all ${mode === 'work' ? `${currentTheme.primary} text-white shadow-xl` : 'text-slate-500 hover:bg-black/5'}`}
        >
          FOCUS (TRAVAIL)
        </button>
        <button 
          onClick={() => { setMode('break'); setTimeLeft(5 * 60); setIsActive(false); }}
          className={`px-8 py-4 rounded-2xl text-xs font-black tracking-widest transition-all ${mode === 'break' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:bg-black/5'}`}
        >
          BREAK (REPOS)
        </button>
      </div>

      {mode === 'work' ? (
        <div className="flex flex-col items-center space-y-12 w-full max-w-lg">
          <div className="relative">
            <div className={`absolute inset-0 rounded-full blur-[80px] opacity-20 ${currentTheme.primary}`} />
            <div className={`w-80 h-80 rounded-full border-[15px] border-slate-200 dark:border-slate-800 flex items-center justify-center relative bg-white dark:bg-slate-900 shadow-2xl transition-all`}>
                <div className={`absolute bottom-0 w-full ${currentTheme.primary} opacity-20 transition-all duration-1000 ease-linear`} style={{ height: `${progress}%` }} />
                <div className={`text-8xl font-black tabular-nums z-10 ${currentTheme.timerColor} tracking-tighter drop-shadow-sm`}>
                  {formatTime(timeLeft)}
                </div>
            </div>
          </div>

          <div className="flex gap-10 items-center">
            <button onClick={() => {setIsActive(false); setTimeLeft(25*60);}} className="p-5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-white transition-all shadow-md"><RotateCcw size={32} /></button>
            <button onClick={() => setIsActive(!isActive)} className={`p-12 rounded-full ${currentTheme.primary} text-white shadow-2xl hover:scale-110 active:scale-90 transition-all shadow-indigo-500/30`}>
              {isActive ? <Pause size={56} fill="currentColor" /> : <Play size={56} fill="currentColor" className="ml-2" />}
            </button>
          </div>

          <div className="w-full space-y-3">
            <p className="text-center text-[10px] font-black uppercase text-slate-400 tracking-[0.3em]">Cible de la session</p>
            <select className={`w-full ${currentTheme.input} rounded-[1.5rem] px-6 py-5 font-bold outline-none shadow-xl border ${currentTheme.border}`} value={selectedTask || ''} onChange={(e) => setSelectedTask(e.target.value)}>
              <option value="">Sélectionner une quête à faire progresser</option>
              {tasks.filter(t => t.status !== TaskStatus.DONE).map(t => <option key={t.id} value={t.id}>{t.title}</option>)}
            </select>
          </div>
        </div>
      ) : (
        <div className={`w-full max-w-2xl ${currentTheme.card} ${currentTheme.radius} border ${currentTheme.border} p-12 text-center shadow-2xl`}>
          <div className="mb-12">
            <h2 className={`text-8xl font-black mb-4 tracking-tighter ${currentTheme.timerColor} tabular-nums`}>{formatTime(timeLeft)}</h2>
            <p className="text-sm font-black uppercase tracking-[0.4em] text-slate-400">Le temps s'écoule... Joue pour l'XP !</p>
          </div>

          <MiniGame onScore={() => onXpGain(15)} />

          <div className="mt-12 flex items-center justify-center gap-4 text-indigo-500 font-black uppercase text-xs tracking-widest animate-bounce">
            <Zap size={24} fill="currentColor" /> Clique sur la cible pour récolter de l'XP !
          </div>
        </div>
      )}
    </div>
  );
};

const MiniGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
  const move = () => {
    setPos({ x: Math.random() * 80 + 10, y: Math.random() * 80 + 10 });
    onScore();
  };
  return (
    <div className="relative w-full h-96 bg-slate-50 dark:bg-black/50 rounded-[3rem] border-4 border-dashed border-slate-200 dark:border-white/5 overflow-hidden shadow-inner cursor-crosshair">
      <button 
        onClick={move} 
        className="absolute w-24 h-24 bg-indigo-600 rounded-full shadow-[0_0_40px_rgba(79,70,229,0.7)] flex items-center justify-center text-white transition-all active:scale-50 hover:scale-110 z-20" 
        style={{ left: `${pos.x}%`, top: `${pos.y}%`, transform: 'translate(-50%, -50%)' }}
      >
        <Zap size={48} fill="white" />
      </button>
      <div className="absolute inset-0 opacity-10 pointer-events-none grid grid-cols-10 grid-rows-10">
        {[...Array(100)].map((_, i) => <div key={i} className="border border-slate-300 dark:border-white/20" />)}
      </div>
    </div>
  );
};

export default Pomodoro;

export enum TaskStatus {
  TODO = 'todo',
  IN_PROGRESS = 'in_progress',
  DONE = 'done'
}

export enum TaskPriority {
  LOW = 'low',
  MEDIUM = 'medium',
  HIGH = 'high'
}

export enum TaskDifficulty {
  EASY = 'easy',
  MEDIUM = 'medium',
  HARD = 'hard'
}

