import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, CheckSquare, Grid2X2, Timer, BarChart3, 
  CalendarDays, Plus, LogOut, Sparkles, User as UserIcon, Palette
} from 'lucide-react';
import { Task, TaskStatus, ThemeType, Unavailability, User, UserData, TaskDifficulty } from './types';
import { THEMES, XP_PER_LEVEL } from './constants';
import { mockAuthService } from './services/mockBackend';
import Dashboard from './components/Dashboard';
import TodoList from './components/Tasks/TodoList';
import EisenhowerMatrix from './components/Matrix/EisenhowerMatrix';
import Pomodoro from './components/Focus/Pomodoro';
import ProgressTracking from './components/Stats/ProgressTracking';
import SmartPlanning from './components/Planning/SmartPlanning';
import TaskModal from './components/Tasks/TaskModal';
import AuthScreen from './components/Auth/AuthScreen';
import ProfileSettings from './components/Settings/ProfileSettings';

type View = 'dashboard' | 'tasks' | 'matrix' | 'planning' | 'focus' | 'stats' | 'settings';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isAuthLoading, setIsAuthLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<View>('dashboard');
  const [tasks, setTasks] = useState<Task[]>([]);
  const [unavailabilities, setUnavailabilities] = useState<Unavailability[]>([]);
  const [theme, setTheme] = useState<ThemeType>('lime');
  const [isTaskModalOpen, setIsTaskModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | undefined>(undefined);

  useEffect(() => {
    const savedUser = localStorage.getItem('evo_current_user');
    if (savedUser) {
      handleLogin(JSON.parse(savedUser));
    } else {
      setIsAuthLoading(false);
    }
  }, []);

  // Persistance synchronisée
  useEffect(() => {
    if (currentUser) {
      const userData: UserData = { tasks, unavailabilities, theme };
      mockAuthService.saveUserData(currentUser.id, userData);
      localStorage.setItem('evo_current_user', JSON.stringify(currentUser));

      const allUsers: any[] = JSON.parse(localStorage.getItem('evo_sql_users') || '[]');
      const updatedUsers = allUsers.map(u => u.id === currentUser.id ? { ...u, ...currentUser } : u);
      localStorage.setItem('evo_sql_users', JSON.stringify(updatedUsers));

      const currentThemeData = THEMES[theme];
      document.body.style.backgroundColor = currentThemeData.bg;
      document.documentElement.style.fontFamily = currentThemeData.font;
      if (theme === 'dark') document.documentElement.classList.add('dark');
      else document.documentElement.classList.remove('dark');
    }
  }, [tasks, theme, unavailabilities, currentUser]);

  const handleLogin = async (user: User) => {
    const userData = await mockAuthService.getUserData(user.id);
    setCurrentUser(user);
    setTasks(userData.tasks);
    setUnavailabilities(userData.unavailabilities);
    setTheme(userData.theme);
    setIsAuthLoading(false);
  };

  const gainXP = (amount: number) => {
    if (!currentUser) return;
    const newXP = currentUser.xp + amount;
    const newLevel = Math.floor(newXP / XP_PER_LEVEL) + 1;
    setCurrentUser({ ...currentUser, xp: newXP, level: newLevel });
  };

  const updateTask = (id: string, updates: Partial<Task>) => {
    setTasks(tasks.map(t => {
      if (t.id === id) {
        const isNowDone = updates.status === TaskStatus.DONE && t.status !== TaskStatus.DONE;
        if (isNowDone) {
          const xpGain = t.difficulty === TaskDifficulty.HARD ? 250 : t.difficulty === TaskDifficulty.MEDIUM ? 150 : 100;
          gainXP(xpGain);
        }
        return { ...t, ...updates, completedAt: isNowDone ? Date.now() : t.completedAt };
      }
      return t;
    }));
  };

  const renderContent = () => {
    if (!currentUser) return null;
    switch (activeTab) {
      case 'dashboard': 
        return <Dashboard 
          tasks={tasks} 
          theme={theme} 
          unavailabilities={unavailabilities} 
          onAddTask={(t) => setTasks([...tasks, { ...t, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now(), actualMinutes: 0 }])} 
          onUpdateTask={updateTask} 
          onAddUnavailability={(u) => setUnavailabilities([...unavailabilities, { ...u, id: Math.random().toString(36).substr(2, 9) }])} 
          onDeleteUnavailability={(id) => setUnavailabilities(unavailabilities.filter(u => u.id !== id))} 
          onStartFocus={() => setActiveTab('focus')}
        />;
      case 'tasks': return <TodoList tasks={tasks} onUpdateTask={updateTask} onDeleteTask={(id) => setTasks(tasks.filter(t => t.id !== id))} onEditTask={(t) => {setEditingTask(t); setIsTaskModalOpen(true);}} onAddTask={() => setIsTaskModalOpen(true)} theme={theme} />;
      case 'matrix': return <EisenhowerMatrix tasks={tasks} onUpdateTask={updateTask} theme={theme} />;
      case 'planning': return <SmartPlanning tasks={tasks} unavailabilities={unavailabilities} theme={theme} />;
      case 'focus': return <Pomodoro theme={theme} tasks={tasks} onUpdateTask={updateTask} onXpGain={gainXP} />;
      case 'stats': return <ProgressTracking tasks={tasks} theme={theme} />;
      case 'settings': return <ProfileSettings user={currentUser} onUpdateUser={setCurrentUser} theme={theme} onThemeChange={setTheme} />;
      default: return null;
    }
  };

  const currentTheme = THEMES[theme];

  return (
    <div className={`min-h-screen flex flex-col md:flex-row ${currentTheme.bg} ${currentTheme.text} transition-all duration-500`}>
      <aside className={`hidden md:flex flex-col w-72 ${currentTheme.card} border-r ${currentTheme.accent} h-screen sticky top-0 z-50 shadow-2xl`}>
        <div className="p-8 flex items-center gap-4">
          <div className={`w-12 h-12 rounded-2xl ${currentTheme.primary} flex items-center justify-center text-white shadow-xl`}>
            <Sparkles size={28} />
          </div>
          <span className="text-3xl font-black tracking-tighter italic">Evo</span>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          {[
            { id: 'dashboard', label: 'Tableau de Bord', icon: LayoutDashboard },
            { id: 'tasks', label: 'Quêtes', icon: CheckSquare },
            { id: 'matrix', label: 'Stratégie', icon: Grid2X2 },
            { id: 'planning', label: 'Planning IA', icon: CalendarDays },
            { id: 'focus', label: 'Mode Focus', icon: Timer },
            { id: 'stats', label: 'Progression', icon: BarChart3 },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as View)}
              className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl transition-all ${activeTab === item.id ? `${currentTheme.button} shadow-lg scale-[1.02]` : 'text-slate-500 hover:bg-black/5 dark:hover:bg-white/5 font-bold'}`}
            >
              <item.icon size={20} />
              <span className="text-sm uppercase tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-6 border-t ${currentTheme.accent} space-y-4">
          <button onClick={() => setActiveTab('settings')} className="w-full flex items-center gap-3 px-6 py-3 rounded-xl text-slate-500 hover:bg-black/5 font-bold transition-all">
            <UserIcon size={20} /> <span className="text-xs uppercase tracking-widest">Profil RPG</span>
          </button>
          <button onClick={() => { localStorage.removeItem('evo_current_user'); setCurrentUser(null); }} className="w-full flex items-center gap-3 px-6 py-3 rounded-xl text-red-500 hover:bg-red-50 font-bold transition-all">
            <LogOut size={20} /> <span className="text-xs uppercase tracking-widest">Déconnexion</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-x-hidden">
        <header className="relative w-full h-72 overflow-hidden shadow-2xl">
          <div className="absolute inset-0 bg-slate-900">
            <img 
              src={currentUser.bannerUrl || "https://images.unsplash.com/photo-1614850523296-d8c1af93d400?q=80&w=2070&auto=format&fit=crop"} 
              alt="Banner" 
              className="w-full h-full object-cover opacity-70 transition-transform duration-1000"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 to-transparent" />
          </div>

          <div className="max-w-6xl mx-auto px-8 flex items-end h-full pb-10 gap-8 relative z-10">
            <div className="relative">
              {/* Avatar avec Décoration (Cadre/Aura) */}
              <div className={`w-40 h-40 rounded-full border-[8px] border-white dark:border-slate-950 overflow-hidden shadow-2xl relative z-10 ${currentUser.decoration || ''}`}>
                <img src={currentUser.avatar} alt="Avatar" className="w-full h-full object-cover" />
              </div>
              <div className={`absolute -bottom-2 -right-2 ${currentTheme.primary} text-white w-14 h-14 rounded-full border-4 border-white dark:border-slate-950 flex items-center justify-center font-black text-xl z-20 shadow-xl`}>
                {currentUser.level}
              </div>
            </div>
            <div className="flex-1 pb-4">
              <h1 className="text-5xl font-black text-white drop-shadow-2xl tracking-tighter mb-4">{currentUser.name}</h1>
              <p className="text-white/60 text-sm font-bold uppercase tracking-widest mb-4 flex items-center gap-2">
                <Sparkles size={16} className="text-amber-400" /> {currentUser.job || "Citoyen d'Evo"}
              </p>
              <div className="flex items-center gap-4">
                <div className="flex-1 max-w-sm h-4 bg-black/50 rounded-full overflow-hidden border border-white/10 backdrop-blur-md">
                  <div className="h-full bg-indigo-500 shadow-[0_0_20px_rgba(99,102,241,1)] transition-all duration-1000" style={{ width: `${(currentUser.xp % XP_PER_LEVEL) / 10}%` }} />
                </div>
                <span className="text-xs font-black uppercase text-white tracking-widest drop-shadow-lg">{currentUser.xp % XP_PER_LEVEL} / {XP_PER_LEVEL} XP</span>
