      {isTaskModalOpen && (
        <TaskModal theme={theme} task={editingTask} onClose={() => { setIsTaskModalOpen(false); setEditingTask(undefined); }} onSubmit={editingTask ? (data) => updateTask(editingTask.id, data) : (data) => { setTasks([...tasks, { ...data, id: Math.random().toString(36).substr(2, 9), createdAt: Date.now(), actualMinutes: 0 }]); setIsTaskModalOpen(false); }} />
      )}
    </div>
  );
};

export default App;

