import React, { useState, useEffect, useRef } from 'react';
import { Task, TaskStatus, ThemeType } from '../../types';
import { THEMES } from '../../constants';
import { Play, Pause, RotateCcw, Brain, Coffee, Zap } from 'lucide-react';

interface PomodoroProps {
  theme: ThemeType;
  tasks: Task[];
  onUpdateTask: (id: string, updates: Partial<Task>) => void;
  onXpGain: (amount: number) => void;
}

const Pomodoro: React.FC<PomodoroProps> = ({ theme, tasks, onUpdateTask, onXpGain }) => {
  const currentTheme = THEMES[theme];
  const [timeLeft, setTimeLeft] = useState(25 * 60);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');
  const [selectedTask, setSelectedTask] = useState<string | null>(null);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    if (isActive && timeLeft > 0) {
      timerRef.current = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      handleTimerComplete();
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isActive, timeLeft]);

  const handleTimerComplete = () => {
    setIsActive(false);
    if (mode === 'work') {
      if (selectedTask) {
        const task = tasks.find(t => t.id === selectedTask);
        if (task) onUpdateTask(selectedTask, { actualMinutes: (task.actualMinutes || 0) + 25 });
      }
      onXpGain(250); 
      setMode('break');
      setTimeLeft(5 * 60);
      setIsActive(true); // Lance la pause automatiquement pour le mini-jeu
    } else {
      setMode('work');
      setTimeLeft(25 * 60);
      setIsActive(false);
    }
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const progress = (mode === 'work' ? 25 * 60 - timeLeft : 5 * 60 - timeLeft) / (mode === 'work' ? 25 * 60 : 5 * 60) * 100;

  return (
    <div className="flex flex-col items-center justify-center space-y-12 py-10 animate-in fade-in duration-500">
      <div className={`flex gap-3 p-2 bg-slate-200/50 dark:bg-slate-900 rounded-3xl backdrop-blur-md`}>
