          onClick={() => { setMode('work'); setTimeLeft(25 * 60); setIsActive(false); }}
          className={`px-8 py-3 rounded-2xl text-xs font-black tracking-widest transition-all ${mode === 'work' ? `${currentTheme.primary} text-white shadow-xl` : 'text-slate-500 hover:bg-black/5'}`}
        >
          MODE TRAVAIL
        </button>
        <button 
          onClick={() => { setMode('break'); setTimeLeft(5 * 60); setIsActive(false); }}
          className={`px-8 py-3 rounded-2xl text-xs font-black tracking-widest transition-all ${mode === 'break' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:bg-black/5'}`}
        >
          MODE REPOS
        </button>
      </div>

      {mode === 'work' ? (
        <div className="flex flex-col items-center space-y-12 w-full max-w-lg">
          <div className="relative">
            {/* Glow constant background */}
            <div className={`absolute inset-0 rounded-full blur-[100px] opacity-20 ${currentTheme.primary}`} />

            <div className={`w-80 h-80 rounded-full border-[15px] border-slate-200 dark:border-slate-800 flex items-center justify-center relative bg-white dark:bg-slate-900 shadow-2xl`}>
                <div className={`absolute bottom-0 w-full ${currentTheme.primary} opacity-20 transition-all duration-1000 ease-linear`} style={{ height: `${progress}%` }} />
                <div className={`text-8xl font-black tabular-nums z-10 ${currentTheme.text} tracking-tighter drop-shadow-sm`}>
                  {formatTime(timeLeft)}
                </div>
            </div>
          </div>

          <div className="flex gap-10 items-center">
            <button onClick={() => {setIsActive(false); setTimeLeft(25*60);}} className="p-5 rounded-full bg-slate-100 dark:bg-white/5 text-slate-400 hover:text-slate-600 transition-all"><RotateCcw size={32} /></button>
            <button onClick={() => setIsActive(!isActive)} className={`p-12 rounded-full ${currentTheme.primary} text-white shadow-2xl hover:scale-105 active:scale-90 transition-all shadow-indigo-500/30`}>
              {isActive ? <Pause size={56} fill="currentColor" /> : <Play size={56} fill="currentColor" className="ml-2" />}
            </button>
          </div>

          <div className="w-full space-y-3">
            <p className="text-center text-[10px] font-black uppercase text-slate-400 tracking-[0.3em]">Cible associée</p>
            <select className="w-full bg-slate-100 dark:bg-white/5 rounded-2xl px-6 py-4 font-bold outline-none shadow-sm" value={selectedTask || ''} onChange={(e) => setSelectedTask(e.target.value)}>
              <option value="">Sélectionner une quête...</option>
              {tasks.filter(t => t.status !== TaskStatus.DONE).map(t => <option key={t.id} value={t.id}>{t.title}</option>)}
            </select>
          </div>
        </div>
      ) : (
        <div className={`w-full max-w-2xl ${currentTheme.card} rounded-[3rem] border ${currentTheme.accent} p-12 text-center shadow-2xl`}>
          <div className="mb-12">
            <h2 className={`text-8xl font-black mb-4 tracking-tighter tabular-nums ${currentTheme.text}`}>{formatTime(timeLeft)}</h2>
            <p className="text-sm font-black uppercase tracking-[0.4em] text-slate-400 italic">Gagne de l'XP pendant que tu te reposes !</p>
          </div>

          <MiniGame onScore={() => onXpGain(20)} />

          <div className="mt-10 flex items-center justify-center gap-4 text-indigo-500 font-black uppercase text-xs tracking-[0.2em] animate-bounce">
            <Zap size={24} fill="currentColor" /> Clique sur la cible pour récolter de l'XP !
          </div>
        </div>
      )}
    </div>
  );
};

const MiniGame = ({ onScore }: { onScore: () => void }) => {
  const [pos, setPos] = useState({ x: 50, y: 50 });
